CREATE TABLE `ads` (
  `id` int(11) NOT NULL,
  `title` varchar(200) NOT NULL,
  `position` enum('navbar-top','header','sidebar-top','sidebar-middle','sidebar-bottom','article-top','article-middle','article-bottom','homepage-banner','category-banner') NOT NULL DEFAULT 'sidebar-top',
  `imageUrl` varchar(500) NOT NULL,
  `linkUrl` varchar(500) DEFAULT NULL,
  `openInNewTab` tinyint(1) DEFAULT 1,
  `priority` int(11) DEFAULT 0,
  `isActive` tinyint(1) DEFAULT 1,
  `startDate` datetime DEFAULT NULL,
  `endDate` datetime DEFAULT NULL,
  `impressions` int(11) DEFAULT 0,
  `clicks` int(11) DEFAULT 0,
  `width` int(11) DEFAULT NULL,
  `height` int(11) DEFAULT NULL,
  `advertiser` varchar(200) DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `targetPages` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Array of page values where ad should appear. Empty = all pages' CHECK (json_valid(`targetPages`)),
  `excludePages` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Array of page values where ad should NOT appear' CHECK (json_valid(`excludePages`)),
  `targetCategories` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Array of category values where ad should appear. Empty = all categories' CHECK (json_valid(`targetCategories`)),
  `excludeCategories` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Array of category values where ad should NOT appear' CHECK (json_valid(`excludeCategories`)),
  `displayFrequency` enum('always','rotation','percentage') DEFAULT 'always' COMMENT 'How often to display this ad',
  `displayPercentage` int(11) DEFAULT 100 COMMENT 'Percentage of time to show ad (0-100)',
  `maxImpressions` int(11) DEFAULT NULL COMMENT 'Maximum total impressions allowed. Null = unlimited',
  `maxClicks` int(11) DEFAULT NULL COMMENT 'Maximum total clicks allowed. Null = unlimited',
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

