INSERT INTO `news_unified` (`id`, `category`, `image`, `title`, `subtitle`, `paragraph`, `publishedDate`, `journalistName`, `journalistImage`, `isFeatured`, `views`, `status`, `createdAt`, `updatedAt`) VALUES
(1, 'main', '/uploads/news/image-1766733959657-687969154.jpg', 'आगामी निर्वाचनका लागि दलहरूलाई आयोगको कडाइः एक–तिहाइ महिला उम्मेदवार अनिवार्य', 'काठमाडौं। निर्वाचन आयोगले फागुन २१ गते तोकिएको प्रतिनिधिसभा सदस्य निर्वाचन र पुस ११ गते घोषित राष्ट्रियसभा निर्वाचनलाई लक्षित गर्दै राजनीतिक दलहरूलाई कडा ढंगले कार्यान्वयन गर्नुपर्ने २० बुँदे निर्देशन जारी गरेको छ। निर्देशनको मुख्य फोकस महिला तथा समावेशी प्रतिनिधित्व सुनिश्चित गर्नेतर्फ केन्द्रित छ।', '<p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; text-align: justify; background-color: rgb(244, 244, 244); font-size: 18px !important;\">काठमाडौं। निर्वाचन आयोगले फागुन २१ गते तोकिएको प्रतिनिधिसभा सदस्य निर्वाचन र पुस ११ गते घोषित राष्ट्रियसभा निर्वाचनलाई लक्षित गर्दै राजनीतिक दलहरूलाई कडा ढंगले कार्यान्वयन गर्नुपर्ने २० बुँदे निर्देशन जारी गरेको छ। निर्देशनको मुख्य फोकस महिला तथा समावेशी प्रतिनिधित्व सुनिश्चित गर्नेतर्फ केन्द्रित छ।</p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; text-align: justify; background-color: rgb(244, 244, 244); font-size: 18px !important;\">आयोगका सहायक प्रवक्ता प्रकाश न्यौपानेका अनुसार राजनीतिक दलसम्बन्धी ऐन, २०७३ को दफा ५७ बमोजिम दर्ता भएका दलहरूलाई निर्वाचनमा समावेशी समानुपातिक प्रतिनिधित्व र सुशासन कायम गर्न निर्देशन दिएको हो।</p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; text-align: justify; background-color: rgb(244, 244, 244); font-size: 18px !important;\"><br></p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; text-align: justify; background-color: rgb(244, 244, 244); font-size: 18px !important;\">निर्देशनअनुसार अब दलहरूले प्रत्यक्षतर्फ उम्मेदवारी दिँदा कम्तीमा एक–तिहाइ महिला उम्मेदवार अनिवार्य रूपमा समावेश गर्नुपर्नेछ। साथै, उम्मेदवार मनोनयन तथा बन्दसूची तयार गर्दा लैङ्गिक र समावेशी संरचना स्पष्ट रूपमा व्यावहारिक बनाउनु पर्नेछ।</p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; text-align: justify; background-color: rgb(244, 244, 244); font-size: 18px !important;\">आयोगले दलहरूलाई सन् २०३० सम्म संसद्मा ४० प्रतिशत महिला प्रतिनिधित्व पुर्‍याउने राष्ट्रिय लक्ष्य प्रभावकारी रूपमा कार्यान्वयन गर्न समेत आन्तरिक नीतिगत संरचना तयार गर्न निर्देशन दिएको छ।</p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; text-align: justify; background-color: rgb(244, 244, 244); font-size: 18px !important;\">दलहरूले निर्वाचनसम्बन्धी गतिविधि सञ्चालन गर्दास्</p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; text-align: justify; background-color: rgb(244, 244, 244); font-size: 18px !important;\">संविधानप्रति निष्ठावान रहनु,</p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; text-align: justify; background-color: rgb(244, 244, 244); font-size: 18px !important;\">विविध जाति, भाषा, धर्म, क्षेत्र र संस्कृतिको सम्मान गर्नु,</p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; text-align: justify; background-color: rgb(244, 244, 244); font-size: 18px !important;\">सामाजिक सद्भावमा खलल पार्ने कुनै पनि गतिविधि नगर्नु—कडा रूपमा अनिवार्य गरिएको छ।</p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; text-align: justify; background-color: rgb(244, 244, 244); font-size: 18px !important;\">आयोगले मतदानस्थल र मतगणनास्थललाई लैङ्गिक तथा अपाङ्गमैत्री बनाउन आवश्यक सहयोग प्रदान गर्न दलहरूलाई आग्रह गरेको छ। साथै, घोषणापत्र तथा नीतिगत दस्तावेजमा लैङ्गिक तथा समावेशी मुद्दाहरूको उचित सम्बोधन अनिवार्य छ।</p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; text-align: justify; background-color: rgb(244, 244, 244); font-size: 18px !important;\">आरक्षणबाहेकका पदहरूमा उम्मेदवारी दिँदा पनि कम्तीमा एक–तिहाइ महिलाको प्रतिनिधित्व तथा सामाजिक विविधता प्रतिबिम्बित हुने समानुपातिक समावेशी सिद्धान्त लागू गर्नुपर्नेछ। दलहरूले आफ्ना प्रशिक्षण, गोष्ठी, सेमिनार तथा छलफलमा महिला र समावेशी समूहको सार्थक सहभागिता सुनिश्चित गर्नुपर्नेछ।</p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; text-align: justify; background-color: rgb(244, 244, 244); font-size: 18px !important;\">प्रचारप्रसारका क्रममास्</p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; text-align: justify; background-color: rgb(244, 244, 244); font-size: 18px !important;\">महिला, बालबालिका, अपाङ्गता भएका व्यक्ति वा समावेशी समूहलाई लक्षित गरी धम्की, गालीगलौज, चरित्र हत्या, अपमान वा निरुत्साहित गर्ने कार्य पूर्ण रूपमा निषेध गरिएको छ।</p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; text-align: justify; background-color: rgb(244, 244, 244); font-size: 18px !important;\">ज्येष्ठ नागरिक, यौनिक तथा लैङ्गिक अल्पसङ्ख्यक र अपाङ्गता भएका व्यक्तिको मर्यादा र आत्मसम्मानमा आँच पुर्‍याउने सामग्री प्रयोग गर्न नपाइनेछ।</p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; text-align: justify; background-color: rgb(244, 244, 244); font-size: 18px !important;\">सामाजिक सञ्जालमा गलत, भ्रामक वा द्वेषपूर्ण सूचना प्रवाह नगर्न दलहरू बाध्य रहनेछन्।</p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; text-align: justify; background-color: rgb(244, 244, 244); font-size: 18px !important;\">एकीकृत अनुशासनका लागि दलहरूले आफ्ना पदाधिकारी तथा सदस्यका लागि आचारसंहिता बनाएर कडाइका साथ लागू गर्नुपर्ने र उल्लंघन गर्नेलाई दलकै विधानअनुसार कारबाही गर्नुपर्ने व्यवस्था पनि आयोगले स्पष्ट गरेको छ।</p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; text-align: justify; background-color: rgb(244, 244, 244); font-size: 18px !important;\">समानुपातिक बन्दसूची पेश गरेपछि दलहरूले त्यसलाई सार्वजनिक गर्नुपर्नेछ। निर्वाचनका क्रममा हिंसा, तोडफोड, जातीय उत्तेजना, बालबालिकाको प्रयोग तथा अन्य अलोकतान्त्रिक गतिविधि कडा रूपमा प्रतिबन्धित गरिएको छ।</p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; text-align: justify; background-color: rgb(244, 244, 244); font-size: 18px !important;\">आयोगले दलहरूलाई आफ्नो घोषणापत्र आयोगमा पेस गरी त्यहीका आधारमा प्रचारप्रसार गर्न तथा अन्य दलको वैध गतिविधिमा बाधा अड्चन सिर्जना नगर्न स्पष्ट निर्देशन दिएको छ।</p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; text-align: justify; background-color: rgb(244, 244, 244); font-size: 18px !important;\">यदि तपाईंलाई यही सामग्रीको अधिक संक्षिप्त संस्करण, अत्यन्त औपचारिक समाचार शैली वा विश्लेषणात्मक प्रस्तुति छुट्टै चाहिएको छ भने म तुरुन्तै तयार गरिदिन्छु।</p>', '2025-12-26 13:10:00', 'नेपाल प्रशासन', NULL, 0, 0, 'published', '2025-12-26 13:10:59', '2025-12-26 13:10:59'),
(2, 'main', '/uploads/news/image-1766734101852-606165121.webp', 'सानो व्यवसाय हो भन्ने लाज’ ले लघु उद्यम प्रवर्द्धनमा बाधा: प्रवक्ता राजु महर्जन', 'लघु, घरेलु तथा साना उद्योगको प्रवर्द्धन नहुनुमा “सानो व्यवसाय हो भन्ने लाज” प्रमुख कारण रहेको ललितपुर महानगरपालिका वडा नं ९ का अध्यक्ष तथा महानगरका प्रवक्ता राजु महर्जनले बताएका छन्।', '<p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; text-align: justify; background-color: rgb(244, 244, 244); font-size: 18px !important;\">लघु, घरेलु तथा साना उद्योगको प्रवर्द्धन नहुनुमा “सानो व्यवसाय हो भन्ने लाज” प्रमुख कारण रहेको ललितपुर महानगरपालिका वडा नं ९ का अध्यक्ष तथा महानगरका प्रवक्ता राजु महर्जनले बताएका छन्। उनका अनुसार यिनै सामाजिक धारणाका कारण स्थानीय समुदाय लघु उद्यम क्षेत्रमा संलग्न हुन नसकेको बताएका हुन् ।महानगरपालिकाको आर्थिक विकास महाशाखा अन्तर्गत लघु, घरेलु तथा साना उद्योग प्रवर्द्धन शाखाले गरीबी निवारणका लागि लघु उद्यम विकास कार्यक्रमअन्तर्गत आयोजना गरेको वडा–स्तरीय अभिमुखिकरण तथा सहभागितामूलक ग्रामीण लेखाजोखा कार्यक्रम सुभारम्भ गरिएको अवसरमा प्रवक्ता महर्जनले यस्तो धारणा सार्वजनिक गरेका हुन्।</p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; text-align: justify; background-color: rgb(244, 244, 244); font-size: 18px !important;\"><img fetchpriority=\"high\" decoding=\"async\" class=\"alignnone size-medium wp-image-1485\" src=\"https://nepalprashasan.com/wp-content/uploads/2025/12/3efbc063-ade8-4b24-a3f2-103e760da278-600x401.jpg\" alt=\"\" width=\"600\" height=\"401\" srcset=\"https://nepalprashasan.com/wp-content/uploads/2025/12/3efbc063-ade8-4b24-a3f2-103e760da278-600x401.jpg 600w, https://nepalprashasan.com/wp-content/uploads/2025/12/3efbc063-ade8-4b24-a3f2-103e760da278-1024x684.jpg 1024w, https://nepalprashasan.com/wp-content/uploads/2025/12/3efbc063-ade8-4b24-a3f2-103e760da278-768x513.jpg 768w, https://nepalprashasan.com/wp-content/uploads/2025/12/3efbc063-ade8-4b24-a3f2-103e760da278-1536x1026.jpg 1536w, https://nepalprashasan.com/wp-content/uploads/2025/12/3efbc063-ade8-4b24-a3f2-103e760da278-300x200.jpg 300w, https://nepalprashasan.com/wp-content/uploads/2025/12/3efbc063-ade8-4b24-a3f2-103e760da278.jpg 2048w\" sizes=\"(max-width: 600px) 100vw, 600px\" style=\"margin-top: 10px; margin-bottom: 10px;\"></p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; text-align: justify; background-color: rgb(244, 244, 244); font-size: 18px !important;\">महर्जनले ललितपुर महानगरका धेरै लघु उद्यममा स्थानीयभन्दा बाहिरी जिल्लाबाट आएका मानिसहरू संलग्न भएको उल्लेख गर्दै, उनीहरूले पनि सीप, तालिम तथा स्रोत–साधनको अभावका बावजूद साना उद्यममा संलग्न हुन सफल भएको बताए। उनका अनुसार पछिल्ला वर्षमा शहरी गरिबी द्रुत रूपमा बढ्दो अवस्थामै लघु उद्यमलाई “शहरी क्षेत्रमा नचाहिने काम” ठान्ने नकारात्मक सोचले उद्यम विकास अवरुद्ध भइरहेको छ।</p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; text-align: justify; background-color: rgb(244, 244, 244); font-size: 18px !important;\">“यो सानो काम, समाजले के भन्ला” भन्ने लाज नै लघु उद्यम प्रवर्द्धनको सबैभन्दा ठूलो बाधक बनेको स्पष्ट पार्दै उनले भने, “तीन दशकदेखि उद्यमीका लागि तालिम सञ्चालन हुँदै आएको भए पनि उद्यमप्रतिको सोचमा परिवर्तन नआएकाले लघु उद्यम तथा सानो उद्योगमा नतिजा अपेक्षित देखिएको छैन् ।”कम धैर्य , छिटो नतिजा खोज्ने प्रवृत्तिका कारण लघु उद्यम क्षेत्रमा अपेक्षित परिवर्तन नआएको उल्लेख गर्दै महर्जनले सोच परिवर्तन गर्दै व्यावसायिक रूपमा अगाडि बढ्न उद्यमीहरूलाई आग्रह गरे।</p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; text-align: justify; background-color: rgb(244, 244, 244); font-size: 18px !important;\"><img decoding=\"async\" class=\"alignnone size-medium wp-image-1487\" src=\"https://nepalprashasan.com/wp-content/uploads/2025/12/8a92b479-4479-4221-a4d4-2503b6451921-600x405.jpg\" alt=\"\" width=\"600\" height=\"405\" srcset=\"https://nepalprashasan.com/wp-content/uploads/2025/12/8a92b479-4479-4221-a4d4-2503b6451921-600x405.jpg 600w, https://nepalprashasan.com/wp-content/uploads/2025/12/8a92b479-4479-4221-a4d4-2503b6451921-1024x692.jpg 1024w, https://nepalprashasan.com/wp-content/uploads/2025/12/8a92b479-4479-4221-a4d4-2503b6451921-768x519.jpg 768w, https://nepalprashasan.com/wp-content/uploads/2025/12/8a92b479-4479-4221-a4d4-2503b6451921-1536x1038.jpg 1536w, https://nepalprashasan.com/wp-content/uploads/2025/12/8a92b479-4479-4221-a4d4-2503b6451921.jpg 2048w\" sizes=\"(max-width: 600px) 100vw, 600px\" style=\"margin-top: 10px; margin-bottom: 10px;\"></p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; text-align: justify; background-color: rgb(244, 244, 244); font-size: 18px !important;\">चालु आर्थिक वर्षमा ललितपुर महानगरका वडा नं। २, ९, १० र २१ लाई पहिलो चरणको कार्यक्रमका रूपमा चयन गरिएको र पहिलो चरणको कार्यक्रम वडा नं. ९ बाट औपचारिक रूपमा सुरु गरिएको आर्थिक विकास महाशाखाअन्तर्गत लघु, घरेलु तथा साना उद्योग शाखाका प्रमुख चन्द्रलाल डंगोलले जानकारी दिए र यस कार्यक्रमको व्यापक प्रचारपसार गर्न कार्यक्रममा सहभागी उद्यमीहरुलाई डंगोलले आव्हान गरेका छन् । उक्त कार्यक्रम तीन वर्षसम्म निरन्तर सञ्चालन हुने बताइएको छ।</p>', '2025-12-26 13:13:00', 'nepal pras', '/uploads/news/journalistImageFile-1766734101853-594026172.png', 0, 0, 'published', '2025-12-26 13:13:21', '2025-12-26 13:13:21'),
(3, 'main', '/uploads/news/image-1766739845738-554084588.jpg', 'इसाई र मुस्लिमहरूले सांस्कृतिक अतिक्रमण गर्दैछन्, भन्न हिचकिचाउनु पर्दैन : डा गोविन्द टण्डन, धर्म तथा संस्कृतिविद्', NULL, '<p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; text-align: justify; background-color: rgb(244, 244, 244); font-size: 18px !important;\"><span style=\"font-weight: bolder;\">नेपालमा सनातन हिन्दु धर्ममाथि संगठित रुपमा आक्रमण भएको जस्तो देखिन्छ, के यो सत्य हो ? अनि, कस्तो अनुभव गर्दै हुनुहुन्छ ?</span></p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; text-align: justify; background-color: rgb(244, 244, 244); font-size: 18px !important;\"><span style=\"font-weight: bolder;\">प्रश्नका लागि धन्यवाद ।</span></p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; text-align: justify; background-color: rgb(244, 244, 244); font-size: 18px !important;\">नेपालको संविधान २०७२ ले नेपाललाई धर्मनिरपेक्ष घोषणा गर्यो, जुन परिस्थिति माओवादी विद्रोह र राजनीतिक परिवर्तनको परिणामस्वरूप निम्तियो भन्दा फरक पर्दैन । यसले संविधानत ः हिजोको ‘हिन्दुराष्ट्र’ लाई राता–रात अन्त्य गर्यो ।</p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; text-align: justify; background-color: rgb(244, 244, 244); font-size: 18px !important;\">यो ‘सनातन हिन्दु धर्ममाथिको घोर आक्रमण’ नै हो भन्दा फरक पर्दैन । यद्यपि संविधानको धारा ४ ले ‘सनातन धर्म’ को संरक्षणको कुरा गरे पनि, यसलाई अलमलाएको ठानिन्छ । यसको मुख्य कारण इसाई र इस्लाम मतलाई बढावा दिन यसो गरिएको व्यापक रूपले सम्झिइन्छ ।</p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; text-align: justify; background-color: rgb(244, 244, 244); font-size: 18px !important;\">धर्मनिरपेक्षताको सबैभन्दा बढी फाइदा गैरहिन्दुहरूले प्राप्त गरे । खुला रूपमा ‘धर्मान्तरण’ खासगरी हिन्दु र बौद्ध धर्म समाजमा व्यापक रूपले हुन पुगेको छ । गाउँगाउँ, बस्तीबस्तीले बावु÷बाजेदेखि मान्दै आएको परम्परागत हिन्दु, बौद्ध धर्मलाई छोडेर नयाँ धर्मलाई आत्मसात् गर्ने प्रवृत्तिले एक्कासी बढावा पायो ।</p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; text-align: justify; background-color: rgb(244, 244, 244); font-size: 18px !important;\">धर्म परिवर्तनको मुद्दा हिजोआज प्रमुख बन्दै गएको छ । मिडियाहरूमा आएका समाचार, छलफल एवं अन्तर्वार्ताहरूलाई हेर्दा विदेशी प्रभाव विशेष गरी पश्चिमी इसाई मिसनरीहरूबाट तराईबाहेकका जिल्लाहरूमा व्यापक रूपले बड्दै गएको छ । तराई÷मधेशतिर इस्लामको व्यापक घुसपैठ देखिन्छ । दुःख,पीडा, गरिबी, अभावबाट फाइदा लिन घरघर, बस्तीबस्तीमा गएर तिमीहरूको धर्म काम नलाग्ने, हाम्रो धर्ममा आयौँ भने यस्तो दिन्छौँ, उस्तो गर्छौँ, हामीमा आओ भनेर अनेक प्रकारको प्रलोभन दिनु कतै पनि उपयुक्त तरिका होइन । यदि यसरी नै उनीहरूको मुलुकमा अन्य धर्म मान्ने मानिसहरू गएर खुलमखुल्ला प्रचारवाजी गर्न सरकारले स्वीकृति दिन्छ ? जरुर पनि संसारमा कहीँ पनि त्यस्तो स्वतन्त्रता दिएको छैन ।</p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; text-align: justify; background-color: rgb(244, 244, 244); font-size: 18px !important;\">नेपालचाहिँ घरघरमा गएर गरिब, दुःखी, सोझासाझा हिन्दु र बौद्ध धर्मावलम्बीहरूलाई इसाई र मुस्लिमहरूले आ–आफ्नो धर्ममा रूपान्तरित गर्दैछन्, जसलाई ‘सांस्कृतिक अतिक्रमण’ भन्न हिचकिचाउनु पर्दैन । सन् २०२१ को जनगणनामा हिन्दुहरूको सङ्ख्या ८१ दशमलव १९५ प्रतिशत देखिन्छ । यसमा इसाईहरूको जनसङ्ख्या १ दशमलव ७६५ पुगेको देखिन्छ । जुन सन् २०११ को जनगण्नामा इसाईहरूको जनसङ्ख्या शुन्य दशमलव १५प्रतिशत थियो । यसले धर्मान्तरण बढ्दै गएको छैन भन्न सकिने स्थिति छैन । यसलाई खतरा मान्नु÷नमान्नु आ–आफ्नो दृष्टिकोण हुन सक्छ ।</p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; text-align: justify; background-color: rgb(244, 244, 244); font-size: 18px !important;\">भारतबाट प्रभावित हिन्दुत्वको विचारधारा कुनै न कुनै रूपबाट नेपालमा प्रचा(प्रसार हुँदैछ । जसले नेपालमा हिन्दु राष्ट्रियवादी समूहहरूलाई बलियो बनाएको ठान्नेहरू पनि छन्, यथार्थमा त्यो सही विश्लेषण होइन । होला, कतै कहीँ अस्थायी रूपले शिक्षा, जागरणका कार्यक्रम चलेका होलान् तर नगन्य छ । ‘सांस्कृतिक उपनिवेशवाद’ जतासुकैबाट आओस्, त्यो देश र जनताको हितको लागि स्वस्थकर हुँदैन ।</p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; text-align: justify; background-color: rgb(244, 244, 244); font-size: 18px !important;\">हालका वर्षहरूमा खासगरी तराई÷मधेश क्षेत्रमा दुर्गा पूजा, गणेश चतुर्थी, हनूमान् जयन्तीजस्ता सनातन हिन्दुधर्मसँग सम्बन्धित पर्व र उत्सवहरूमा ढुङ्गा हान्ने, झडप हुनेजस्ता घटनाले कफ्र्यू नै लगाउनु परेको घटनाहरू पनि भए । सन् २०२५ को असोजमा जनकपुरधाममा दुर्गा मूर्ति विसर्जनको बेला मस्जिदबाट ढुङ्गा हान्ने, झडपबाजी हुनेजस्ता घटनाले धेरैजना घाइते भएका समाचारहरू पनि आए । त्यसैगरी सन् २०२५ को भाद्रमा जनकपुरधाममा गणेश मूर्तिको विसर्जनमा इस्लामिक समूहबाट आक्रमण भयो ।</p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; text-align: justify; background-color: rgb(244, 244, 244); font-size: 18px !important;\">त्यसभन्दा झन्डै एक वर्ष अगाडि २०२४ को अप्रिलमा सुनसरीमा हनूमान कथा कार्यक्रममा मुस्लिमहरूबाट आक्रमण भएर एकजना हिन्दुको दुखद् मृत्यु भएको घटना अझै ताजा छ ।</p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; text-align: justify; background-color: rgb(244, 244, 244); font-size: 18px !important;\">यी घटनाहरू मधेश अर्थात तराई क्षेत्रमा बढी छन् । जसलाई स्थानीय राजनीति र धार्मिक उन्मादले बढाएको देखिन्छ । सनातन हिन्दुहरूले दलित र अल्पसंख्यकहरूमाथि खासगरी छूवाछूतको नाममा मन्दिर प्रवेशको विषयलाई लिएर विभिन्न किसिमको मानसिक र शारीरिक हिंसाका घटनाहरू बाहिर नआएका होइनन्, आएका छन् । यी र यस्ता घटनाहरूलाई हाम्रोजस्तो बहुभाषी, बहुसम्प्रदायी, बहुसंस्कृति भएको मुलुकमा कुनै पनि तह र तप्काबाट आउन दिनु हुँदैन ।</p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; text-align: justify; background-color: rgb(244, 244, 244); font-size: 18px !important;\">नेपालमा युगौँयुगदेखि विद्यमान हुँदै आएको धार्मिक सद्भाव र सहिष्णुताले अन्य मुलुकहरूमा जस्तो रक्तरञ्जित अवस्था नआउँला भन्ने आशा गरौँ । यसो भए पनि देखिएका चुनौतीलाई न्यूनीकरण गर्न देहायका विषयहरूमा ध्यान पु¥याउनु जरुरी छ ।</p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; text-align: justify; background-color: rgb(244, 244, 244); font-size: 18px !important;\">कानूनी प्रवर्तन र संरक्षण– रूपान्तरण र धार्मिक हिंसाको कानून कडाइका साथ लागू गर्नु पर्छ । मन्दिर र मस्जिदहरूको संरक्षण र उत्सवहरूमा सुरक्षा बढाउनु पर्छ । नेपालको फौजदारी संहिताले रूपान्तरणलाई दण्डनीय बनाएको छ । यसलाई प्रभावकारी बनाउनु जरुरी छ ।<br>शिक्षा र जागरण– स्कूलहरूमा सनातन धर्मको इतिहास र सहिष्णुताको शिक्षा दिनु पर्छ । सामाजिक सञ्जालमा अफवाह रोक्नु सक्नु पर्छ । सही र उपयुक्त सनातन जागरण अभियानू लाई विस्तार गर्नु पर्छ ।</p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; text-align: justify; background-color: rgb(244, 244, 244); font-size: 18px !important;\">संवाद र समावेशी नीति– हिन्दु, मुस्लिम, इसाई र बौद्ध नेताहरूबीच वेलावेलामा छलफल, कुराकानी गरी सौहार्दतालाई बढाउँदै अल्पसंख्यकहरूलाई पनि सनातन हिन्दु संस्कृतिमा स्थान दिएर समावेश गर्न सक्नु पर्छ र नेपालमा विद्यमान धार्मिक सहिष्णुतालाई प्रोत्साहन गर्नु पर्छ ।</p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; text-align: justify; background-color: rgb(244, 244, 244); font-size: 18px !important;\">राजनीतिक इच्छाशक्ति– हिन्दु राष्ट्र पुनस्र्थापनाको मागलाई जनमतसंग्रहमार्फत समाधान गर्ने वा संवैधानिक संशोधन गर्नु पर्छ । तर, हिंसालाई कुनै पनि हालतमा राजनीतिकरण गरिनु हुन्न । केही राजनीतिक दलहरूले पनि यस विषयलाई छलफलको विषय बनाएका छन् ।</p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; text-align: justify; background-color: rgb(244, 244, 244); font-size: 18px !important;\">समुदाय स्तरको एकता – स्थानीय स्तरमा सनातन हिन्दुधर्म संस्कृतिको असल शिक्षालाई बाँड्दै स्थानीय समुदायलाई संगठित गर्नु पर्छ र बाह्य प्रभाव भारत, चीन एवं पश्चिमी मुलुकहरूलाई सन्तुलित अवस्थामा राख्ने काम गरिनु पर्छ ।</p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; text-align: justify; background-color: rgb(244, 244, 244); font-size: 18px !important;\">&nbsp;</p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; text-align: justify; background-color: rgb(244, 244, 244); font-size: 18px !important;\">यी कदमहरूको व्यावहारिक प्रयोगबाट तनाव कम हुन सक्छ । उदाहरणका लागि, नेपालमा प्राचीन कालदेखि असल हिन्दुस्तानको रूपमा सनातन धर्म संरक्षित छ र सहिष्णुताले नै यसलाई बलियो बनाएको छ । मुख्य रूपमा यस्तो चिन्ता राजनीतिक परिवर्तन, धार्मिक रूपान्तरणको डर र साम्प्रदायिक तनावबाट प्रेरित छ । तर, नेपालमा धार्मिक सहिष्णुताको भाव उच्च छ। हिन्दु र बौद्धहरूबीच प्राचीन कालदेखि सहकार्य छ ।</p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; text-align: justify; background-color: rgb(244, 244, 244); font-size: 18px !important;\">अर्को महत्त्वपूर्ण कुरा नेपाली समाजमा सनातन हिन्दुधर्ममा पुस्तौदेखि चल्दै आएको छूवाछुत, सानोठूलो जातका कुरा पनि बाधक छन्, यसमा पनि समयानुसार परिवर्तन ल्याउनु जरुरी छ । यस सम्बन्धमा भएका ऐनकानूननको परिपालन तथा कार्यान्वयन पनि त्यत्तिकै जरुरी छ । आफ्नो समाजमा आफ्नोपन पक्ष भएको, अस्वीकार गरिएको, ताडना र प्रताडना बेहोर्नु परेको जस्ता कैयौँ कारणले पनि सनातन हिन्दुधर्मलाई छोडेर अन्यत्र धर्मान्तरित भएको घटनाहरूलाई हेर्दा सबैको लागि हुने समाजको परिकल्पना आवश्यक छ । यसका लागि सुधारकहरू तथा समाजमा सुख, शान्ति ल्याउन चाहनेहरू आ–आफ्नो क्षेत्रबाट सक्रिय हुनुपर्ने पनि त्यत्ति नै आवश्यक छ ।</p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; text-align: justify; background-color: rgb(244, 244, 244); font-size: 18px !important;\">हो, सनातन हिन्दु धर्मभित्र पुस्तौँदेखि चल्दै आएको छुवाछूत र जातीय भेदभावले धेरैलाई पीडा दिएको छ र अझै पनि दिइरहेको छ । यो पीडा केवल सामाजिक अपमानमा मात्र सीमित छैन । आर्थिक, शैक्षिक र राजनीतिक अवसरबाट पनि वञ्चित गराउने माध्यम बनेको छ । यही कारणले कैयौँ दलित तथा सीमान्तकृत समुदायका मानिसहरूले धर्मान्तरणलाई एउटा विकल्प ठानेका छन् । दिनानुदिन घटित भइरहेको यस्तो गम्भीर विषयलाई लुकाउनु वा अस्वीकार गर्नु समस्याको समाधान हुन सक्तैन । यस विषयमा पनि चनाखो हुन र गम्भीर छलफल गरी निष्कर्षमा पुग्नु जरुरी भइसकेको छ ।</p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; text-align: justify; background-color: rgb(244, 244, 244); font-size: 18px !important;\">गाउँगाउँमा अझै पनि मन्दिर प्रवेश, पानीको धारा, अन्तरजातीय विवाह आदि कुरामा भेदभाव कायमै छ । पीडितले उजुरी गर्न डराउँछन्, प्रहरीले मुद्दा दर्ता गर्न आनाकानी गर्छ, अदालतसम्म पुग्ने मुद्दा नगण्य छन् । धर्मान्तरण एउटा “फेसन” वा विदेशी पैसाको लोभमात्र हो भन्ने भनाइ देखिन्छ, सुनिन्छ, तर जब मानिसले आफ्नो भनेर स्वीकार गरेको समाजमा पनि इज्जत, सम्मान र समान अवसर पाइँदैन, जब उसलाई “अछूत” भनिन्छ । मन्दिर पस्न दिइँदैन, अन्तरजातीय विवाह गरे परिवार÷समाजले बहिष्कार गर्छ भने ऊ विकल्प खोज्न बाध्य हुन्छ । जहाँ सबै समान हुन् भन्ने भावना व्यावहारिक रूपमा देखिन्छ, त्यहाँ आफ्नो सामाजिक वर्चस्वलाई जोगाउन पनि ऊ पुग्न बाध्य हुन्छ भन्ने यथार्थवादी सोचलाई राम्ररी सम्झेर र बुझेर व्यक्ति, परिवार, समाज र सरकारले यस विषयमा गम्भीरतापूर्वक सोच्नु पर्ने आवश्यकता छ ।</p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; text-align: justify; background-color: rgb(244, 244, 244); font-size: 18px !important;\">विकृति र कुरीतिलाई हटाउँदै, फाल्दै जाने तर असल संस्कृति र परम्परालाई हरहालतमा जोगाउने साहस आवश्यक छ ।<br>छुवाछूत गर्नेहरूलाई ऐन कानूनअनुसारको दण्ड जरीवाना गर्दै भेदभाव कतै उपयुक्त छैन भन्ने सन्देश समाजमा प्रवाहित गर्नु जरुरी छ । गाउँगाउँमा नागरिक अधिकारकर्मी र प्रहरीको संयुक्त टोलीले अनुगमन गर्ने व्यवस्था पनि मिलाउनु आवश्यक छ ।</p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; text-align: justify; background-color: rgb(244, 244, 244); font-size: 18px !important;\">स्कूलको पाठ्यक्रममा नै “हामी सबै समान हौँ” भन्ने कुरा प्रभावकारी रूपमा पढाउनु पर्छ । गाउँबस्तीमा अन्तरजातीय भोज, साझा पूजापाठ, सांस्कृतिक कार्यक्रमहरूको आयोजन पनि त्यत्तिकै जरुरी छ । शिक्षा, रोजगारी र सम्पत्तिमा पहुँच नबढाइकन केवल ‘धर्म नछोड ’भन्दैमा कोही टेर्नेवाला हुँदैनन् । सबैको लागि स्वतन्त्रतापूर्वक सम्मानसाथ बाँच्न पाउने वातावरणको निर्माण जरुरी छ ।</p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; text-align: justify; background-color: rgb(244, 244, 244); font-size: 18px !important;\"><span style=\"font-weight: bolder;\">अन्तमा</span><br>सनातन हिन्दुधर्म जोगाउन तथा यहाँ देखापर्दै गएको ‘धर्मान्तरण’ लाई हटाउन समाजमा विद्यमान भेदभाव र अन्यायलाई जसरी हुन्छ छिटो व्यावहारिक रूपमा हटाउनु पनि एकदमै जरुरी भइसकेको छ । जबसम्म हामी आफ्नै घरमा सबैलाई समान व्यवहार गर्दैनौँ, तबसम्म “सबैको लागि हुने समाज” को परिकल्पना अधुरो रहन्छ । यसका लागि सुधारकहरूको खाँचो त छँदैछ, तर सबैभन्दा ठूलो कुरा त हामी सबैले आफैँबाट सुरु गर्नुपर्छ, आफ्नो व्यवहार, आफ्नो सोच र आफ्नो परिवारबाट । यदि हामीले समयमै गर्नु पर्ने सुधार गरेनौँ भने इतिहासले हामीलाई कहिल्यै माफ गर्ने छैन ।</p>', '2025-12-26 14:48:00', 'nepal123', '/uploads/news/journalistImageFile-1766739845739-819317894.png', 0, 0, 'published', '2025-12-26 14:49:05', '2025-12-26 14:49:05'),
(4, 'main', '/uploads/news/image-1766739940893-107755337.jpg', 'इसाई र मुस्लिमहरूले सांस्कृतिक अतिक्रमण गर्दैछन्, भन्न हिचकिचाउनु पर्दैन : डा गोविन्द टण्डन, धर्म तथा संस्कृतिविद्', NULL, '<p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; text-align: justify; background-color: rgb(244, 244, 244); font-size: 18px !important;\">नेपालको संविधान २०७२ ले नेपाललाई धर्मनिरपेक्ष घोषणा गर्यो, जुन परिस्थिति माओवादी विद्रोह र राजनीतिक परिवर्तनको परिणामस्वरूप निम्तियो भन्दा फरक पर्दैन । यसले संविधानत ः हिजोको ‘हिन्दुराष्ट्र’ लाई राता–रात अन्त्य गर्यो ।</p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; text-align: justify; background-color: rgb(244, 244, 244); font-size: 18px !important;\">यो ‘सनातन हिन्दु धर्ममाथिको घोर आक्रमण’ नै हो भन्दा फरक पर्दैन । यद्यपि संविधानको धारा ४ ले ‘सनातन धर्म’ को संरक्षणको कुरा गरे पनि, यसलाई अलमलाएको ठानिन्छ । यसको मुख्य कारण इसाई र इस्लाम मतलाई बढावा दिन यसो गरिएको व्यापक रूपले सम्झिइन्छ ।</p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; text-align: justify; background-color: rgb(244, 244, 244); font-size: 18px !important;\">धर्मनिरपेक्षताको सबैभन्दा बढी फाइदा गैरहिन्दुहरूले प्राप्त गरे । खुला रूपमा ‘धर्मान्तरण’ खासगरी हिन्दु र बौद्ध धर्म समाजमा व्यापक रूपले हुन पुगेको छ । गाउँगाउँ, बस्तीबस्तीले बावु÷बाजेदेखि मान्दै आएको परम्परागत हिन्दु, बौद्ध धर्मलाई छोडेर नयाँ धर्मलाई आत्मसात् गर्ने प्रवृत्तिले एक्कासी बढावा पायो ।</p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; text-align: justify; background-color: rgb(244, 244, 244); font-size: 18px !important;\">धर्म परिवर्तनको मुद्दा हिजोआज प्रमुख बन्दै गएको छ । मिडियाहरूमा आएका समाचार, छलफल एवं अन्तर्वार्ताहरूलाई हेर्दा विदेशी प्रभाव विशेष गरी पश्चिमी इसाई मिसनरीहरूबाट तराईबाहेकका जिल्लाहरूमा व्यापक रूपले बड्दै गएको छ । तराई÷मधेशतिर इस्लामको व्यापक घुसपैठ देखिन्छ । दुःख,पीडा, गरिबी, अभावबाट फाइदा लिन घरघर, बस्तीबस्तीमा गएर तिमीहरूको धर्म काम नलाग्ने, हाम्रो धर्ममा आयौँ भने यस्तो दिन्छौँ, उस्तो गर्छौँ, हामीमा आओ भनेर अनेक प्रकारको प्रलोभन दिनु कतै पनि उपयुक्त तरिका होइन । यदि यसरी नै उनीहरूको मुलुकमा अन्य धर्म मान्ने मानिसहरू गएर खुलमखुल्ला प्रचारवाजी गर्न सरकारले स्वीकृति दिन्छ ? जरुर पनि संसारमा कहीँ पनि त्यस्तो स्वतन्त्रता दिएको छैन ।</p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; text-align: justify; background-color: rgb(244, 244, 244); font-size: 18px !important;\">नेपालचाहिँ घरघरमा गएर गरिब, दुःखी, सोझासाझा हिन्दु र बौद्ध धर्मावलम्बीहरूलाई इसाई र मुस्लिमहरूले आ–आफ्नो धर्ममा रूपान्तरित गर्दैछन्, जसलाई ‘सांस्कृतिक अतिक्रमण’ भन्न हिचकिचाउनु पर्दैन । सन् २०२१ को जनगणनामा हिन्दुहरूको सङ्ख्या ८१ दशमलव १९५ प्रतिशत देखिन्छ । यसमा इसाईहरूको जनसङ्ख्या १ दशमलव ७६५ पुगेको देखिन्छ । जुन सन् २०११ को जनगण्नामा इसाईहरूको जनसङ्ख्या शुन्य दशमलव १५प्रतिशत थियो । यसले धर्मान्तरण बढ्दै गएको छैन भन्न सकिने स्थिति छैन । यसलाई खतरा मान्नु÷नमान्नु आ–आफ्नो दृष्टिकोण हुन सक्छ ।</p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; text-align: justify; background-color: rgb(244, 244, 244); font-size: 18px !important;\">भारतबाट प्रभावित हिन्दुत्वको विचारधारा कुनै न कुनै रूपबाट नेपालमा प्रचा(प्रसार हुँदैछ । जसले नेपालमा हिन्दु राष्ट्रियवादी समूहहरूलाई बलियो बनाएको ठान्नेहरू पनि छन्, यथार्थमा त्यो सही विश्लेषण होइन । होला, कतै कहीँ अस्थायी रूपले शिक्षा, जागरणका कार्यक्रम चलेका होलान् तर नगन्य छ । ‘सांस्कृतिक उपनिवेशवाद’ जतासुकैबाट आओस्, त्यो देश र जनताको हितको लागि स्वस्थकर हुँदैन ।</p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; text-align: justify; background-color: rgb(244, 244, 244); font-size: 18px !important;\">हालका वर्षहरूमा खासगरी तराई÷मधेश क्षेत्रमा दुर्गा पूजा, गणेश चतुर्थी, हनूमान् जयन्तीजस्ता सनातन हिन्दुधर्मसँग सम्बन्धित पर्व र उत्सवहरूमा ढुङ्गा हान्ने, झडप हुनेजस्ता घटनाले कफ्र्यू नै लगाउनु परेको घटनाहरू पनि भए । सन् २०२५ को असोजमा जनकपुरधाममा दुर्गा मूर्ति विसर्जनको बेला मस्जिदबाट ढुङ्गा हान्ने, झडपबाजी हुनेजस्ता घटनाले धेरैजना घाइते भएका समाचारहरू पनि आए । त्यसैगरी सन् २०२५ को भाद्रमा जनकपुरधाममा गणेश मूर्तिको विसर्जनमा इस्लामिक समूहबाट आक्रमण भयो ।</p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; text-align: justify; background-color: rgb(244, 244, 244); font-size: 18px !important;\">त्यसभन्दा झन्डै एक वर्ष अगाडि २०२४ को अप्रिलमा सुनसरीमा हनूमान कथा कार्यक्रममा मुस्लिमहरूबाट आक्रमण भएर एकजना हिन्दुको दुखद् मृत्यु भएको घटना अझै ताजा छ ।</p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; text-align: justify; background-color: rgb(244, 244, 244); font-size: 18px !important;\">यी घटनाहरू मधेश अर्थात तराई क्षेत्रमा बढी छन् । जसलाई स्थानीय राजनीति र धार्मिक उन्मादले बढाएको देखिन्छ । सनातन हिन्दुहरूले दलित र अल्पसंख्यकहरूमाथि खासगरी छूवाछूतको नाममा मन्दिर प्रवेशको विषयलाई लिएर विभिन्न किसिमको मानसिक र शारीरिक हिंसाका घटनाहरू बाहिर नआएका होइनन्, आएका छन् । यी र यस्ता घटनाहरूलाई हाम्रोजस्तो बहुभाषी, बहुसम्प्रदायी, बहुसंस्कृति भएको मुलुकमा कुनै पनि तह र तप्काबाट आउन दिनु हुँदैन ।</p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; text-align: justify; background-color: rgb(244, 244, 244); font-size: 18px !important;\">नेपालमा युगौँयुगदेखि विद्यमान हुँदै आएको धार्मिक सद्भाव र सहिष्णुताले अन्य मुलुकहरूमा जस्तो रक्तरञ्जित अवस्था नआउँला भन्ने आशा गरौँ । यसो भए पनि देखिएका चुनौतीलाई न्यूनीकरण गर्न देहायका विषयहरूमा ध्यान पु¥याउनु जरुरी छ ।</p>', '2025-12-26 14:50:00', 'np ', '/uploads/news/journalistImageFile-1766739940893-913388388.png', 0, 0, 'published', '2025-12-26 14:50:40', '2025-12-26 14:50:40'),
(5, 'main', '/uploads/news/image-1766740012741-829961437.jpg', 'परराष्ट्रमन्त्री शर्माले लिए शपथ', 'नेपाली सेनाका पूर्वरथी बालानन्द शर्माले परराष्ट्रमन्त्री पदमा पद तथा गोपनीयताको शपथ लिएका छन् ।  ', '<div class=\"ai_summary_block\" style=\"background-color: rgba(0, 13, 77, 0.024); padding: 30px; margin-bottom: 30px; font-family: Mukta, sans-serif; font-size: 16px;\"><ul class=\"ai_summary_block_list\" style=\"margin-left: 16px;\"><li style=\"list-style: disc; font-weight: 600; color: rgba(0, 0, 0, 0.8); line-height: 1.8;\">नेपाली सेनाका पूर्वरथी बालानन्द शर्माले ११ पुस, काठमाडौँमा परराष्ट्रमन्त्री पदमा पद तथा गोपनीयताको शपथ लिएका छन्।</li></ul></div><p style=\"font-size: 22px; margin-bottom: 28px; line-height: 1.8; font-family: Mukta, sans-serif;\">११ पुस, काठमाडौँ । नेपाली सेनाका पूर्वरथी बालानन्द शर्माले परराष्ट्रमन्त्री पदमा पद तथा गोपनीयताको शपथ लिएका छन् ।</p>', '2025-12-26 14:51:00', 'online khabar', NULL, 0, 0, 'published', '2025-12-26 14:51:52', '2025-12-26 14:51:52'),
(6, 'main', '/uploads/news/image-1766770645309-815907386.jpg', 'निर्वाचन र मानव अधिकारः सुर्खेतमा जेन-जेड प्रतिनिधि सहित सरोकारवालाबीच छलफल', 'निर्वाचन र मानव अधिकारः सुर्खेतमा जेन-जेड प्रतिनिधि सहित सरोकारवालाबीच छलफल', '<p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; font-size: 16px; text-align: justify; background-color: rgb(244, 244, 244);\">कर्णाली प्रदेशको राजधानी सुर्खेतको वीरेन्द्रनगरमा जेन-जेड प्रतिनिधि सहित सरोकारवालाबीच निर्वाचन र मानव अधिकार विषयमा छलफल गरिएको छ।</p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; font-size: 16px; text-align: justify; background-color: rgb(244, 244, 244);\">अनौपचारिक क्षेत्र सेवा केन्द्र (इन्सेक) कर्णाली प्रदेश कार्यालयको आयोजनामा बुधबार वीरेन्द्रनगरमा आगामी फागुन २१ गते हुने निर्वाचनको लागि<span style=\"font-weight: bolder;\">&nbsp;‘निर्वाचन र मानव अधिकार’</span>&nbsp;विषयक अन्तरक्रिया कार्यक्रम गरिएको इन्सेक कर्णाली प्रदेश कार्यालय प्रमुख नारायण सुवेदीले रंगिन पाटीलाई जानकारी दिए।</p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; font-size: 16px; text-align: justify; background-color: rgb(244, 244, 244);\">अन्तरक्रिया कार्यक्रममा निर्वाचनको तयारी, मानव अधिकारको अवस्था, निर्वाचनमा युवाको सहभागिता तथा जेन- जेड आन्दोलनको भूमिकाबारे राजनीतिक दलका प्रतिनिधि, युवा मानवअधिकार कर्मी, जेन-जेड प्रतिनिधि सहित सरोकारवालाबीच छलफल गरिएको इन्सेक कर्णालीका प्रमुख सुवेदीले रंगिन पाटीलाई बताए ।</p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; font-size: 16px; text-align: justify; background-color: rgb(244, 244, 244);\">कार्यक्रममा प्रदेश निर्वाचन कार्यालयका सूचना अधिकारी नन्दराम चौलागाईं ले नव–युवालाई मतदान प्रक्रियामा सहभागी गराउने उद्देश्यसहित मतदाता नामावली अद्यावधिक कार्य प्रविधिमैत्री बनाइएको जानकारी दिए।</p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; font-size: 16px; text-align: justify; background-color: rgb(244, 244, 244);\">उनले निर्वाचनको विषयमा आवश्यकताअनुसार सबै सरोकारवाला निकायसँग समन्वय भइरहेको र साथै निर्वाचनमा प्रबेक्षक छनोटका क्रममा कुनै पनि राजनीतिक दलमा आबद्ध व्यक्तिलाई सहभागी नगराउन अनुरोध समेत गरे । सूचना अधिकारीले जिल्ला बाहिर तथा विदेशमा रहेका नेपाली नागरिकलाई मतदानको अधिकार सुनिश्चित गर्ने विषयमा भने हालसम्म कुनै पनि कानुनी व्यवस्था नभएको समेत उल्लेख गरे ।</p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; font-size: 16px; text-align: justify; background-color: rgb(244, 244, 244);\">मानव अधिकार आयोग कर्णाली प्रदेश कार्यालयका सूचना अधिकारी मान बहादुर कार्कीले निर्वाचन शान्तिपूर्ण, भयरहित र स्वतन्त्र हुनुपर्नेमा जोड दिए।</p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; font-size: 16px; text-align: justify; background-color: rgb(244, 244, 244);\">मानव अधिकारका विषयमा आ–आफ्नो अनुकूल सिद्धान्त बनाउनु गलत हुने भन्दै साझा मूल्य र मान्यतामा आधारित अभ्यास आवश्यक रहेको बताए।</p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; font-size: 16px; text-align: justify; background-color: rgb(244, 244, 244);\">कार्यक्रममा बोल्दै जेनजेड अगुवा तथा कर्णाली प्रदेश संयोजक सुप्रिया राज्यलक्ष्मी शाहीले जेन–जेडलाई हेर्ने दृष्टिकोण सकारात्मक हुनुपर्ने बताइन्।</p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; font-size: 16px; text-align: justify; background-color: rgb(244, 244, 244);\">निर्वाचन सफल बनाउन हरेक क्षेत्रले आफ्नो भूमिका खेल्नुपर्ने भन्दै न्यायका लागि अझै पनि संघर्ष गर्नुपर्ने धारणा राखिन्। उनले पार्टीभन्दा नेतृत्वका कमजोरीले समस्या सिर्जना हुने गरेको बताइन् । गत भदौमा भएको जेन-जेड आन्दोलन भ्रष्टाचार अन्त्य र देशमा सुशासन कायम राख्न गरिएको बताउँदै आगामी निर्वाचनमा हरेक राजनीतिक दलले युवालाई प्राथमिकता राखेर आगामी निर्वाचनमा उम्मेद्वार बनाउनु पर्ने उनले जोड दिइन्।</p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; font-size: 16px; text-align: justify; background-color: rgb(244, 244, 244);\">त्यस्तै कार्यक्रममा जेन–जेड अभियन्ता प्रकाश खड्काले जेन–जेडलाई आतंककारीको रूपमा चित्रण गर्नु गलत भएको बताए।</p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; font-size: 16px; text-align: justify; background-color: rgb(244, 244, 244);\">राष्ट्रिय स्वतन्त्र पार्टी (रास्वपा) का सह–महामन्त्री तथा कर्णाली प्रदेश प्रवक्ता हरि अधिकारीले कार्यक्रममा उठेका प्रश्न हरुको जवाफ दिंदै नेपालका अन्य राजनीतिक दलभन्दा युवालाई समेट्ने पार्टी रास्वपा भएको दाबी गरे।</p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; font-size: 16px; text-align: justify; background-color: rgb(244, 244, 244);\">उनले जेन-जेड उमेर समूहका युवा पुस्तालाई ‘जेन–जेड डर लाग्दो होइन, रहर लाग्दो’ हुनुपर्ने उल्लेख गर्दै यो निर्वाचन पछि पनि युवाले नेतृत्व गर्न नसके जेन–जेड आन्दोलनको औचित्य नहुने बताए ।</p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; font-size: 16px; text-align: justify; background-color: rgb(244, 244, 244);\">सम्पूर्ण राजनीतिकदलहरुले आगामी निर्वाचनको मुख्य एजेन्डा नै सुशासन र भ्रष्टाचार नियन्त्रण गर्ने बनाउनुपर्ने र</p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; font-size: 16px; text-align: justify; background-color: rgb(244, 244, 244);\">आवश्यक परे आगामी निर्वाचनमा अन्य दलका राम्रो उम्मेदवारलाई समेत सहयोग गर्न सकिने बताए।</p>', '2025-12-26 23:22:25', 'sac', NULL, 0, 0, 'published', '2025-12-26 23:22:25', '2025-12-26 23:22:25'),
(7, 'main', '/uploads/news/image-1766770708040-101821394.jpg', 'सेनाद्वारा दुर्घटनामा उद्धार र आगलागी नियन्त्रण', NULL, '<p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; font-size: 16px; text-align: justify; background-color: rgb(244, 244, 244);\">नेपाली सेनाले देशका केही स्थानमा भएका विपत्तिमा उद्धार तथा आगलागी नियन्त्रण गरेका समाचार प्राप्त भएका छन् ।</p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; font-size: 16px; text-align: justify; background-color: rgb(244, 244, 244);\">पाल्पाको निस्दी– ४ मित्यल स्थित चिउरेबासमा यात्रुबाहक जिप सडकबाट खसेर दुर्घटना भयो । यो दुर्घटनामा नेपाली सेनाको दि फेमस महिन्द्र दल गणबाट खटिएको टोलीले अन्य सुरक्षा निकाय तथा स्थानीयको सहयोगमा ८ जना घाइतेको उद्धार गरेको छ ।</p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; font-size: 16px; text-align: justify; background-color: rgb(244, 244, 244);\">यसैगरी दाङ्गको राप्ती– २ कठाहास्थित फोहोर सङ्कलन केन्द्रमा भएको आगलागी ज्वालादल गणबाट खटिएको उद्धार टोलीले प्रशासन अन्य सुरक्षा निकाय तथा स्थानीयको सहयोगमा नियन्त्रणमा लिएको छ ।</p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; font-size: 16px; text-align: justify; background-color: rgb(244, 244, 244);\">पोखरा बस्ने एक जना पुरूष प्याराग्लाईडिङ गर्ने क्रममा फेवातालमा डुबेका र सेनाको महावीर गण, रेञ्जरबाट खट्टिएको उद्धार टोलीले सकुशल उद्धार गरेको सैनिक मुख्यालयले जनाएको छ</p>', '2025-12-26 23:23:28', 's', NULL, 0, 0, 'published', '2025-12-26 23:23:28', '2025-12-26 23:23:28'),
(8, 'main', '/uploads/news/image-1766770778548-872560154.jpg', 'अनामनगरमा शुद्ध मह', 'अनामनगरमा शुद्ध मह', '<p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; font-size: 16px; text-align: justify; background-color: rgb(244, 244, 244);\">राजधानी अनामनगरको अर्नी खाना घरमा डुँडमा पालेको मौरीबाट उत्पादित चाकासहितको विशुद्ध मह बिक्रीका लागि बट्टामा राख्दै अर्नी कृषि उत्पादन अर्गानिक पसलका सुनिल रिजाल ।</p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; font-size: 16px; text-align: justify; background-color: rgb(244, 244, 244);\">रिजालका अनुसार यहाँ गाउँमा किसानले विना विषादि उत्पादन गरेका फलफुल, खाद्यान्न, मह, जडिबुटीदेखि दुग्ध पदार्थहरु&nbsp; खरिद गर्दै उपभोक्तासम्म पुर्याइने गरेको छ । पछिल्लो समय अर्गानिक उत्पादनको माग बढ्दो रहेको सञ्चालक उमेश बोहराको भनाइ छ ।</p>', '2025-12-26 23:24:00', 'ssac', NULL, 0, 0, 'published', '2025-12-26 23:24:38', '2025-12-26 23:24:38'),
(9, 'main', '/uploads/news/image-1766999650761-671308324.jpg', 'भयरहित वातावरणका बनाउन सञ्चार क्षेत्रको भूमिका महत्वपूर्ण : प्रहरी महानिरीक्षक कार्की', NULL, '<p style=\"font-size: 22px; line-height: 36px; margin-top: 0.2em; color: rgb(42, 42, 42); font-family: Mukta, -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, Arial, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;;\">लुम्बिनी — प्रहरी महानिरीक्षक दानबहादुर कार्कीले समाजमा भयरहित वातावरणमा नागरिकले जीवनयापन गर्न पाउने वातावरणका लागि सञ्चार क्षेत्रको महत्वपूर्ण योगदान रहेको बताए ।</p><a class=\"static-sponsor\" target=\"_blank\" href=\"https://easybank.siddharthabank.com/\" style=\"cursor: pointer; text-decoration: none; color: rgb(34, 34, 34); transition: 0.3s ease-in; display: block; text-align: center; font-family: Mukta, -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, Arial, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;; font-size: 22px;\"><img src=\"https://assets-cdn.ekantipur.com/uploads/source/ads/easy-bank-gif-women-900x100-30112025121143.gif\" style=\"width: 748px; object-fit: cover; filter: none;\"></a><div class=\"row\" style=\"display: flex; -webkit-box-flex: 0; flex: 0 1 auto; -webkit-box-orient: horizontal; -webkit-box-direction: normal; flex-flow: wrap; margin-right: -1rem; margin-left: -1rem; color: rgb(42, 42, 42); font-family: Mukta, -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, Arial, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;; font-size: 22px;\"><div class=\"col-md-12 desc-content landscape\" style=\"-webkit-box-flex: 0; flex: 0 0 100%; padding-right: 1rem; padding-left: 1rem; max-width: 100%;\"><p style=\"line-height: 36px; margin-top: 0.2em;\">लुम्बिनी प्रेस क्लबद्वारा आयोजित न्यूज फेस्टिवलको समापनमा महानिरीक्षक कार्कीले प्रहरी र सञ्चारकर्मी बीचको सम्बन्धलाई नङ र मासुको रुपमा चित्रित गर्दै लुकेका अपराध बाहिर ल्याउन सञ्चार क्षेत्रले निर्वाह गरेको भूमिका महत्वपूर्ण भएको बताए&nbsp;।</p><p style=\"line-height: 36px;\">लुम्बिनीस्थित बेबी बुद्धमा आयोजित कार्यक्रममा उनले खोज पत्रकारिताले लुकेका कैयौं अपराध बाहिर ल्याउन सञ्चारकर्मीले सहयोग पुर्याइरहेकाे बताए&nbsp;। ‘कहिलेकाँही घटनास्थलमा प्रहरीभन्दा पहिले सञ्चारकर्मी पुगेर अपराधमा संलग्नलाई पक्राउ गर्ने आधार प्रमाणहरु पाउँदा अनुसन्धानमा पनि सहयोग पुगेको छ,’ उनले भने&nbsp;। अफवाह, मिथ्या र भ्रामक सूचना चिर्न पत्रकारले तथ्यमा आधारित, सन्तुलित र जिम्मेवार समाचार दिएर नागरिकमा चेतनाको स्तर बढाउनु पर्ने उनले बताए&nbsp;।</p><p style=\"line-height: 36px;\">लुम्बिनी प्रेस क्लबको ११ औं स्थापना दिवसका अवसरमा आयोजित हेरिटेज वाकको पनि महानिरीक्षक कार्कीले शुभारम्भ गरेका थिए&nbsp;। पर्सा चोकदेखि हेरिटेज वाक गर्दै टोली बेबी बुद्धमा पुगेर समापन गरिएको थियो&nbsp;।</p><p style=\"line-height: 36px;\">कार्यक्रममा नेपाल पत्रकार महासंघ अध्यक्ष निर्मला शर्मा, प्रेस काउन्सिल अध्यक्ष डा. कुमार आचार्य, लुम्बिनी सांस्कृतिक नगरपालिकाका कार्यबाहक नगरप्रमुख कल्पना हरिजन, लुम्बिनी विकास कोषका सदस्य सचिव दीपक श्रेष्ठलगायतले सञ्चार क्षेत्रको भूमिकाबारे बोलेका थिए&nbsp;। तीन दिने न्यूज फेस्टिवलमा नेपाल र भारतका पत्रकार, पर्यटन व्यवसायी, उद्यमी, भिक्षु र लामा गुरु सहभागी थिए&nbsp;।</p></div></div>', '2025-12-29 14:59:00', 'kantipur', NULL, 0, 0, 'published', '2025-12-29 14:59:10', '2025-12-29 14:59:10'),
(10, 'main', '/uploads/news/image-1766999696096-400102024.jpg', 'इन्टरपोलबाट रेड नोटिस जारी भएका व्यक्ति यूएईबाट पक्राउ', NULL, '<p style=\"font-size: 22px; line-height: 36px; margin-top: 0.2em; color: rgb(42, 42, 42); font-family: Mukta, -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, Arial, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;;\">काठमाडौँ — ठगी, आपराधिक विश्वासघात तथा आपराधिक लाभ&nbsp; र सङ्गठित अपराध मुद्दामा इन्टरपोलबाट रेड नोटिस जारी भएका फरार प्रतिवादी संयुक्त अरब इमिरेट्स (यूएई) बाट पक्राउ परेका छन् ।</p><a class=\"static-sponsor\" target=\"_blank\" href=\"https://easybank.siddharthabank.com/\" style=\"cursor: pointer; text-decoration: none; color: rgb(34, 34, 34); transition: 0.3s ease-in; display: block; text-align: center; font-family: Mukta, -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, Arial, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;; font-size: 22px;\"><img src=\"https://assets-cdn.ekantipur.com/uploads/source/ads/easy-bank-gif-women-900x100-30112025121143.gif\" style=\"width: 748px; object-fit: cover; filter: none;\"></a><div class=\"row\" style=\"display: flex; -webkit-box-flex: 0; flex: 0 1 auto; -webkit-box-orient: horizontal; -webkit-box-direction: normal; flex-flow: wrap; margin-right: -1rem; margin-left: -1rem; color: rgb(42, 42, 42); font-family: Mukta, -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, Arial, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;; font-size: 22px;\"><div class=\"col-md-12 desc-content landscape\" style=\"-webkit-box-flex: 0; flex: 0 0 100%; padding-right: 1rem; padding-left: 1rem; max-width: 100%;\"><p style=\"line-height: 36px; margin-top: 0.2em;\"><span data-mce-style=\"font-size: 21px; white-space: normal;\" style=\"font-size: 21px; line-height: 36px;\">एनसीबी अबुधाबी यूएईको समन्वयमा यूएईबाट पक्राउ परेका बागलुङ नगरपालिका–२ श्रीनगर घर भएका जावेद अनवरद्दीनलाई सम्बन्धित मुद्दामा कारबाही गर्ने प्रयोजनार्थ आज नेपाल फिर्ता ल्याइएको प्रहरीले जनाएको छ&nbsp;।</span></p><p style=\"line-height: 36px;\"><span data-mce-style=\"font-size: 21px; white-space: normal;\" style=\"font-size: 21px; line-height: 36px;\">फरार रहेका उनलाई अन्तर्राष्ट्रियस्तरमा खोजतलास एवं पक्राउ गर्न प्रहरी प्रधान कार्यालय, इन्टरपोल शाखाको अनुरोधमा इन्टरपोल महासचिवालयबाट २०७७ भदौ ८ गते रेड नोटिस जारी भएको थियो&nbsp;।</span></p><p style=\"line-height: 36px;\"><span data-mce-style=\"font-size: 21px; white-space: normal;\" style=\"font-size: 21px; line-height: 36px;\">उनलाई आवश्यक अनुसन्धान एवम् कारबाहीका लागि केन्द्रीय अनुसन्धान ब्युरो बुझाइएको प्रहरी प्रधान कार्यालय इन्टरपोल शाखाले जनाएको छ&nbsp;।</span></p></div></div>', '2025-12-29 14:59:00', 'hero ', NULL, 0, 0, 'published', '2025-12-29 14:59:56', '2025-12-29 14:59:56');
