INSERT INTO `sports` (`id`, `image`, `title`, `subtitle`, `publishedDate`, `journalistName`, `journalistImage`, `createdAt`, `updatedAt`, `paragraph`) VALUES
(15, '/uploads/sports/image-1766734282572-797924496.jpg', 'हेटौडामा राज्य रक्षक होइन भक्षक बन्दै छ : अभियन्ता दुर्गा प्रसाईँ', 'सरकार जनताका लागि रक्षक हो, भनिन्छ । तर, यसको ठीक उल्टो नेपाल सरकार भने रक्षक नभएर भक्षक बनेको उदाहरण मकवानपुरको हेटौडामा देखिएको छ ।', '2025-12-26 07:31:00', 'np', '/uploads/sports/journalistImage-1766734282572-7136862.png', '2025-12-26 07:31:22', '2025-12-26 07:31:22', '<p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; text-align: justify; background-color: rgb(244, 244, 244); font-size: 18px !important;\">सरकार जनताका लागि रक्षक हो, भनिन्छ । तर, यसको ठीक उल्टो नेपाल सरकार भने रक्षक नभएर भक्षक बनेको उदाहरण मकवानपुरको हेटौडामा देखिएको छ ।</p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; text-align: justify; background-color: rgb(244, 244, 244); font-size: 18px !important;\">मकवानपुरको हेटौडा बजार क्षेत्रमा सडक विस्तारको नाममा उचित मुआब्जा वितरण नै नगरी धमाधम घरमा डोजर लगाउने काम सरकारले गरिरहेको छ । ‘लामो समयदेखि बसोबास गर्दै आएका बासिन्दालाई मुआब्जा पनि नदिएर घरमा डोजर चलाउने वा दीर्घकालीन व्यवस्थापनको योजना पनि नबनाई सुकुम्बासीका टहरा भत्काउनेजस्ता काम गर्नु अति गैरजिम्मेवार हो ।’– राष्ट्र बचाउ, महाअभियानका अध्यक्ष तथा अभियन्ता दुर्गा प्रसाईँले भन्नु भएको छ ।</p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; text-align: justify; background-color: rgb(244, 244, 244); font-size: 18px !important;\">उहाँले भन्नु भयो,–‘मानिसलाई भूमिहीन बनाउने तथा सुकुम्बासी बनाउने काम तत्काल बन्द गरियोस् ।’</p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; text-align: justify; background-color: rgb(244, 244, 244); font-size: 18px !important;\">अभियन्ता प्रसाईँले भारतको उदाहरण पनि दिनु भएको छ । उहाँले ‘धेरै टाढा उदाहरण खोज्नै पर्दैन, छिमेकी भारतमै कुनै गाउँमा रेलवे ट्र्याक वा सडक सञ्जाल विस्तार गर्नुपर्ने भएमा त्यहाँका नागरिकहरू सबैभन्दा धेरै खुसी हुन्छन्। किनकि त्यहाँ सरकारले व्यक्तिका जग्गा–जमिनमा काम गर्नुपरेमा सरकारी दरभन्दा तीन गुणा बढी मुआब्जा पहिला नै दिएरमात्रै परियोजना अघि बढाउँछ।’</p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; text-align: justify; background-color: rgb(244, 244, 244); font-size: 18px !important;\">महाअभियानका अध्यक्ष प्रसाईँले भारतको भन्दा नेपालमा ठीक उल्टो भएको भन्दै सरकारलाई खवरदारी गर्नु भएको छ । उहाँले भन्नु भयो,– ‘राज्य भक्षक होइन, रक्षक बनोस्, हामी सरकारसँग निरन्तर वार्ता र संवादमा छौं।, बार्ता नटुटोस्, छलफल नै समाधान हो। सडक बिस्तारको लागि बैकल्पिक मार्ग पनि पर्योग गर्न सकिन्छ। राज्यको काम जनतालाई विस्थापित गर्नु होइन, सुरक्षित राख्नु हो।’</p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; text-align: justify; background-color: rgb(244, 244, 244); font-size: 18px !important;\">सडक डिभिजन हेटौँडाले मंसिर ५ गते १५ दिने सूचना जारी गर्दै मंसिर २० गतेदेखि हेटौँडाको रातोमाटेदेखि बुद्धचोक हुँदै राप्ती पुलसम्म र बुद्धचोकदेखि सामरीसम्मका ५ सय ३१ घर टहरा हटाउने तयारी गरेको छ ।</p>'),
(16, '/uploads/sports/image-1766734369550-412252503.jpg', 'BIN पावर समिट : ऊर्जा क्षेत्रमा लगानी बढाउन नीतिगत हस्तक्षेप आवश्यक – वरिष्ठ उपाध्यक्ष डाँगी', 'भारतमा सम्पन्न साउथ एसिया (बिआईएन) पावर समिट, २०२५ मा ऊर्जा क्षेत्रमा लगानी बढाउन नीतिगत हस्तक्षेप आवश्यक रहेको विज्ञहरुले बताएका छन् ।', '2025-12-26 07:32:00', 'nepal', '/uploads/sports/journalistImage-1766734369550-423427584.png', '2025-12-26 07:32:49', '2025-12-26 07:32:49', '<p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; text-align: justify; background-color: rgb(244, 244, 244); font-size: 18px !important;\">भारतमा सम्पन्न साउथ एसिया (बिआईएन) पावर समिट, २०२५ मा ऊर्जा क्षेत्रमा लगानी बढाउन नीतिगत हस्तक्षेप आवश्यक रहेको विज्ञहरुले बताएका छन् ।</p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; text-align: justify; background-color: rgb(244, 244, 244); font-size: 18px !important;\">भारतीय उद्योग परिसंघ (CII) ले नयाँ दिल्लीमा आयोजना गरेको समिटमा भुटान, भारत र नेपाल (BIN) को ऊर्जा क्षेत्रमा लामो समयदेखि सक्रिय ऊर्जा उद्यमीहरु र सरकारी अधिकारीहरुको सहभागीता रहेको थियो ।</p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; text-align: justify; background-color: rgb(244, 244, 244); font-size: 18px !important;\">नेपालको निजी क्षेत्रको प्रतिनिधित्व गर्दै स्वतन्त्र ऊर्जा उत्पादकहरुको संस्था, नेपाल (इप्पान)का वरिष्ठ उपाध्यक्ष मोहनकुमार डाँगीको नेतृत्वमा ५ सदस्यीय टोलीले सम्मेलनमा भाग लिएको थियो । सरकारी अधिकारीहरुका तर्फबाट भने ऊर्जा, जलस्रोत तथा सिंचाई मन्त्रालयका सहसचिव एवं विद्युत विकास विभागका उपमहानिर्देशक नुतन कुमार शर्मा नेतृत्वको टोली सहभागी भएको थियो ।</p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; text-align: justify; background-color: rgb(244, 244, 244); font-size: 18px !important;\">सहसचिव शर्माले भारतीय उद्योग परिसंघ र परराष्ट्र मन्त्रालयले संयुक्त रुपमा आयोजना गरेको सम्मेलनको उद्घाटन सत्रमा आफ्नो धारणा राख्दै दक्षिण एसियाको विद्युत माग धान्न आवश्यक स्वच्छ ऊर्जा उत्पादनका लागि नेपाल सक्षम रहने बताएका थिए ।</p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; text-align: justify; background-color: rgb(244, 244, 244); font-size: 18px !important;\">Accelerating Investment in Power Sector: Intervention Required विषयक सत्रमा धारणा राख्दै इप्पानका वरिष्ठ उपाध्यक्ष मोहनकुमार डाँगीले ऊर्जा क्षेत्रमा तीब्र लगानी बढाउन बिआईएन देशहरुमा नीतिगत हस्तक्षेप आवश्यक रहेको बताए ।</p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; text-align: justify; background-color: rgb(244, 244, 244); font-size: 18px !important;\">नेपाल सरकारले सन २०३५ भित्र २८ हजार ५०० मेगावाट विद्युत उत्पादन पुर्‍याउने लक्ष्य लिएर अघि बढेको स्मरण गराउँदै वरिष्ठ उपाध्यक्ष डाँगीले त्यसका लागि ४६.५ अर्ब डलर लगानी आवश्यक रहेकोले बिटुबी लगानी लिएर नेपाल आउनको लागि आग्रह गरेका थिए ।</p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; text-align: justify; background-color: rgb(244, 244, 244); font-size: 18px !important;\">उनले विद्युत उत्पादन, वितरण, खुला पहुँच र पूर्वाधार निर्माणमा ठूलो लगानी आवश्यक रहेकोले बिआईएन राष्ट्रहरुले दीर्घकालीन र छोटो अवधिमा अन्तरदेशिय विद्युत व्यापारलाई सहयोग पुर्‍याउने क्षेत्रहरुमा लगानी बढाउने सम्भावित रणनीतिहरुमा जोड दिनुपर्ने बताए ।</p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; text-align: justify; background-color: rgb(244, 244, 244); font-size: 18px !important;\">डाँगीले भारत र बंगलादेशमा स्वच्छ ऊर्जाको ठूलो माग रहेको र नेपालमा जल ऊर्जा उत्पादनको अपार सम्भावना रहेकोले बिआईएन देशहरुको आपसी सहकार्यबाट भारत र बंगलादेशको स्वच्छ ऊर्जाको माग पूरा गर्न नेपाली ऊर्जा उत्पादकहरु सक्षम रहेको बताए ।</p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; text-align: justify; background-color: rgb(244, 244, 244); font-size: 18px !important;\">उनले नेपालमा अहिले ४ हजार मेगावाट विद्युत उत्पादन क्षमता पुगिसकेको, ५ हजार ५०० मेगावाट क्षमताका आयोजनाहरु निजी क्षेत्रको अगुवाइमा निर्माणाधिन रहेको र अर्को ३ हजार मेगावाट क्षमताका आयोजनाहरु वित्तिय व्यवस्थापन गरेर निर्माणमा जाने अन्तिम तयारीमा रहेको पनि बताए । त्यसबाहेक निजी क्षेत्रले अर्को २० हजार मेगावाट क्षमताका जलविद्युत आयोजनाकोहरुको अध्ययन गरिरहेको पनि डाँगीले बताएका थिए ।</p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; text-align: justify; background-color: rgb(244, 244, 244); font-size: 18px !important;\">Strategizing for Enhancing Energy Cooperation through Cross Border Power Trade सत्रमा बोल्दै इप्पानका उपाध्यक्ष आशिष गर्गले विगत दुई वर्षमा यस क्षेत्र (BIN)मा बिजुलीको माग बढ्दो क्रममा रहेकोले विद्युत व्यापार बढाउनु आवश्यक रहेको बताए ।</p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; text-align: justify; background-color: rgb(244, 244, 244); font-size: 18px !important;\">यसै सत्रको छलफलमा भाग लिएका नेपाल विद्युत प्राधिकरणका उपकार्यकारी निर्देशक सुभाश कुमार मिश्रले बिआईएन विद्युत व्यापारमा केही चुनौतीहरू भएपनि योजना र विशिष्ट रणनीति बनाएर अघि बढेमा विद्युत व्यापारलाई तीव्रता दिन सकिने बताएका थिए ।</p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; text-align: justify; background-color: rgb(244, 244, 244); font-size: 18px !important;\">खुला पहुँच र विद्युत व्यापारलाई प्रवर्द्धन गर्न उत्पादन, वितरण र प्रसारणमा उचित योजना हुनुपर्ने, यसको लागि संरचनात्मक, व्यावसायिक र नियामक पक्षहरूले नीतिगत हस्तक्षेपहरू गरेर वृहद विद्युत व्यापार परिदृश्यको लागि तयार हुनुपर्ने गर्गको धारणा थियो ।</p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; text-align: justify; background-color: rgb(244, 244, 244); font-size: 18px !important;\">Creating a Framework to Promote Power Exchanges: Challenges and Opportunities सत्रमा बोल्दै इप्पानका उपाध्यक्ष उत्तम भ्लोन लामाले पहिले विद्युत व्यापार दीर्घकालीन आधारमा हुने गरेको भएपनि अहिले भारतले ल्याएको नयाँ क्रस बोर्डर विद्युत व्यापार निर्देशिका अनुसार डे अहेड मार्केट (DAM) मा दैनिक रुपमा पनि अन्तरदेशिय विद्युत व्यापार सम्भव भएको बताए ।</p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; text-align: justify; background-color: rgb(244, 244, 244); font-size: 18px !important;\">नेपालबाट अहिले भारतमा १ हजार मेगावाटभन्दा बढी र बंगलादेशमा ४० मेगावाट विद्युत निर्यात भइरहेको छ । बंगलादेशमा निर्यात भइरहेको विद्युतको महसुल स्थिर रहेको र भारतीय बजारमा स्थिर र डेअहेड दुवै तरिकाले विद्युत आयात/निर्यात भइरहेको पनि लामाले बताए ।</p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; text-align: justify; background-color: rgb(244, 244, 244); font-size: 18px !important;\">उनले यस क्षेत्रमा अहिले नेपालको सरकारी तवरबाट मात्रै विद्युत व्यापार भइरहेको र निजी क्षेत्रले विद्युत व्यापारका लागि सम्पूर्ण तयारी पुरा गरेर अनुमति पर्खिरहेको धारणा राखेका थिए ।</p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; text-align: justify; background-color: rgb(244, 244, 244); font-size: 18px !important;\">अझै पनि, क्रस बोर्डर विद्युत एक्सचेन्जमा व्यापार प्रारम्भिक चरणमा रहेकोले यस क्षेत्रमा विद्युत एक्सचेन्जहरूको प्रवेश बढाउन उचित रणनीति बनाउनु आवश्यक रहेको लामाको भनाई थियो ।</p><p style=\"margin-bottom: 0.8rem; color: rgb(51, 51, 51); font-family: Arial, sans-serif; text-align: justify; background-color: rgb(244, 244, 244); font-size: 18px !important;\">सम्मेलनमा इप्पानका पूर्वकार्यसमिति सदस्य अभिज्ञा मल्लले Promoting Hydropower and Pump Storage: Prospects and Progress so far सत्रको प्यानल डिस्कसनमा र राष्ट्रिय प्रसारण ग्रिड कम्पनी लिमिटेड (RPGCL) का प्रमुख कार्यकारी अधिकृत सागर श्रेष्ठले One Sun One World One Grid Connectivity: Creating Sustainability though Grid Integration सत्रको प्यानल डिस्कसनमा भाग लिएका थिए</p>'),
(17, '/uploads/sports/image-1766749594611-41861785.jpg', 'kathmandu', NULL, '2025-12-26 11:46:34', 's', NULL, '2025-12-26 11:46:34', '2025-12-26 11:46:34', '<p style=\"font-size: 22px; margin-bottom: 28px; line-height: 1.8; font-family: Mukta, sans-serif; text-align: justify;\">काठमाडौँ । फिल्म ‘झरीपछिको इन्द्रेणी’ लाई शो नदिएर क्यूएफएक्स हलले हेला गरेको यसका निर्देशक अर्जुन घिमिरे ‘पाँडे’ ले गुनासो गरेका छन् । पत्रकार भेटघाटमा उनले उक्त हलले फिल्मलाई हेला गरेको बताए ।</p><p style=\"font-size: 22px; margin-bottom: 28px; line-height: 1.8; font-family: Mukta, sans-serif; text-align: justify;\">उक्त हलले देशभर जम्मा ५ शो दिएको उनको भनाइ छ । पाँडेले भने, ‘एउटा फिल्मले क्यूएफएक्समा पाउने शो यति हो र ? सुरुमा थोरै शो दिए पनि दर्शक बढेपछि शो बढाउँछ भन्ने लागेको थियो । तर अहिलेसम्म बढाइएको छैन’ उनले भने ।</p>'),
(18, '/uploads/sports/image-1766818167776-889000648.jpg', 'जसपा नेपालको प्रदेशस्तरीय विरोध सभा आजदेखि', 's', '2025-12-27 06:49:00', 'journalist ', NULL, '2025-12-27 06:49:27', '2025-12-27 06:49:27', '<h2 class=\"single-heading\" style=\"margin-bottom: 0.5rem; font-weight: 600; line-height: 1.3; color: rgba(0, 0, 0, 0.9); font-size: 35px; transition: 0.2s ease-in-out; font-family: Mukta; background-color: rgba(255, 255, 255, 0.9);\"><p style=\"margin-bottom: 1rem; color: rgb(33, 37, 41); font-size: 22px; font-weight: 400; text-align: justify;\">काठमाडौँ । जनता समाजवादी पार्टी (जसपा)नेपालले प्रदेशस्तरीय विरोध सभा गर्न लागेको छ । संविधान संशोधन, निर्वाचन क्षेत्र पुर्निनिर्धारण, जनताद्वारा प्रत्यक्ष निर्वाचित कार्यकारी राष्ट्रपति प्रणालीको व्यवस्थालगायतका २८ बुँदे विभिन्न माग र राष्ट्रिय मुद्दा उठाउँदै विभिन्न संघर्षका कार्यक्रम गर्दै आएको जसपा नेपालले आजदेखि प्रदेशस्तरीय विरोध सभा गर्न लागेको हो ।&nbsp;</p><p style=\"margin-bottom: 1rem; color: rgb(33, 37, 41); font-size: 22px; font-weight: 400; text-align: justify;\">&nbsp;प्रदेशस्तरीय विरोध सभाका कार्यक्रमअन्तर्गत आज विराटनगरमा पार्टीले विरोध सभा गर्न लागेको छ ।</p><p style=\"margin-bottom: 1rem; color: rgb(33, 37, 41); font-size: 22px; font-weight: 400; text-align: justify;\"></p><p style=\"margin-bottom: 1rem; color: rgb(33, 37, 41); font-size: 22px; font-weight: 400; text-align: justify;\">पुस १४ गते मधेस प्रदेशको जनकपुरमा, १५ गते वीरगन्जमा र १७ गते लुम्बिनी प्रदेशको भैरहवामा विरोध सभाको आयोजना गर्न लागिएको हो । विरोध सभालाई पार्टीका अध्यक्ष उपेन्द्र यादवलगायतका शीर्ष नेताहरूले सम्बोधन गर्ने बताइएको छ ।</p><p style=\"margin-bottom: 1rem; color: rgb(33, 37, 41); font-size: 22px; font-weight: 400; text-align: justify;\">जसपा नेपालले संघर्षका कार्यक्रमअन्तर्गत संसदीय निर्वाचन क्षेत्रका विभिन्न सहर बजारहरूमा विरोध कार्यक्रम र कोण सभा गर्नुका साथै पार्टीले उठाएका माग र मुद्दाहरू अंकित प्लेकार्ड, ब्यानर सहित जिल्ला सदरमुकामहरूका जिल्ला प्रशासन कार्यालयहरू अगाडी शान्तिपूर्ण धर्ना तथा जिल्ला स्तरीय विरोध सभा/जन सभा गरेको थियो ।&nbsp;&nbsp;</p></h2>'),
(19, '/uploads/sports/image-1766819326539-89879429.jpg', 'trump', 'ascxasc', '2025-12-27 07:08:46', 'dc', NULL, '2025-12-27 07:08:46', '2025-12-27 07:08:46', NULL),
(20, '/uploads/sports/image-1766902975122-811675513.webp', '‘स्वास्थ्य क्षेत्रमा सरकारी र गैरसरकारी निकायबीच सहकार्य आवश्यक’ : पूर्वराष्ट्रपति यादव', '‘स्वास्थ्य क्षेत्रमा सरकारी र गैरसरकारी निकायबीच सहकार्य आवश्यक’ : पूर्वराष्ट्रपति यादव', '2025-12-27 01:31:00', 'NP', NULL, '2025-12-27 07:16:59', '2025-12-28 06:22:55', '<p style=\"margin-bottom: 1rem; color: rgb(33, 37, 41); font-family: Mukta; font-size: 22px; text-align: justify;\">काठमाडौँ । पूर्वराष्ट्रपति डा. रामवरण यादवले स्वास्थ्य क्षेत्रमा सुधार ल्याउन सरकारी र गैरसरकारी निकायबीच सहकार्य जरुरी रहेको बताएका छन् ।&nbsp;</p><p style=\"margin-bottom: 1rem; color: rgb(33, 37, 41); font-family: Mukta; font-size: 22px; text-align: justify;\">आज धनुषाको हंसपुर नगरपालिका-६ टिल्हीस्थित तपसी बाबा विद्यालयमा आयोजित बृहत् नि:शुल्क स्वास्थ्य शिविर उद्घाटन गर्दै उनले बिग्रँदै गएको स्वास्थ्य अवस्थामा सुधारका लागि आफ्नै खेतबारीमा उत्पादित खाद्यान्न सेवन गर्न सुझावसमेत दिए । समाज सेवाभन्दा ठूलो धर्म अरु केही नभएको भन्दै पूर्वराष्ट्रपति डा. यादवले स्वास्थ्य शिविर आयोजना गरेर राम्रो काम गरिएको भन्दै आयोजकको प्रशंसा गरेका छन् ।&nbsp;</p><p style=\"margin-bottom: 1rem; color: rgb(33, 37, 41); font-family: Mukta; font-size: 22px; text-align: justify;\">नेपाली काँग्रेसका नेता रामकृष्ण यादवले दुर्गम क्षेत्रमा विशेषज्ञसहित बृहत् स्वास्थ्य शिविर र नि:शुल्क औषधि वितरण कार्यक्रम गरेर सराहनीय काम गरिएको बताए । उनले शिविरमा उपचार गराएर स्वास्थ्य लाभ लिनका लागि सबैलाई आग्रह गरे ।&nbsp;</p><p style=\"margin-bottom: 1rem; color: rgb(33, 37, 41); font-family: Mukta; font-size: 22px; text-align: justify;\">हंसपुर नगरपालिका उपप्रमुख दुर्गीदेवी मण्डलले हंसपुरमा नेपाल-भारतका विशेषज्ञ चिकित्सकको सहभागितामा सुरु भएको स्वास्थ्य शिविरबाट धेरै जना लाभान्वित हुने विश्वास व्यक्त गरिन् ।</p><p style=\"margin-bottom: 1rem; color: rgb(33, 37, 41); font-family: Mukta; font-size: 22px; text-align: justify;\">शिविरका आयोजक समाजसेवी गंगाराम यादवले यस क्षेत्रका गरिब तथा विपन्न जनताले भारत तथा काठमाडौँमा उपचार गर्न बाध्य हुनुपरेको भन्दै शिविरबाट केही राहत हुने बताए । कार्यक्रममा मधेस स्वास्थ्य विज्ञान प्रतिष्ठानका डा. दिग्विजयकुमार ठाकुर, तपसी बाबा विद्यालयका प्रधानाध्यापक मदनकुमार महरा, वरिष्ठ चिकित्सक डा गौरांगा मिश्र, जनकपुरधामका पूर्वनगरप्रमुख बजरंगप्रसाद साहलगायतले सम्बोधन गरेका थिए।</p><p style=\"margin-bottom: 1rem; color: rgb(33, 37, 41); font-family: Mukta; font-size: 22px; text-align: justify;\">शनिबारसम्म सञ्चालन हुने शिविरमा मुटु, मिर्गौला, बाँझोपन, स्त्री, बालरोग, नाक, कान, घाँटी, हाडजोर्नी, आँखाका साथै सामान्य उपचारसहित नि:शुल्क औषधि वितरण गर्ने कार्यक्रम रहेको छ ।&nbsp;</p>'),
(21, '/uploads/sports/image-1767008849483-927801621.jpg', 'वडाका २ सय ४० विद्यार्थीलाई अल्लोको झोला वितरण', 'वडाका २ सय ४० विद्यार्थीलाई अल्लो', '2025-12-29 11:47:29', 'sacs', NULL, '2025-12-29 11:47:29', '2025-12-29 11:47:29', '<p style=\"font-size: 22px; line-height: 36px; margin-top: 0.2em; color: rgb(42, 42, 42); font-family: Mukta, -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, Arial, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;;\">सामुदायिक विद्यालयका १ देखि ५ सम्मका विद्यार्थीहरुलाई झोला वितरण गरिएको वडाध्यक्ष सन्तोष लिम्बूले जानकारी दिए&nbsp;।</p><p style=\"font-size: 22px; line-height: 36px; color: rgb(42, 42, 42); font-family: Mukta, -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, Arial, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;;\">गाउँको उत्पादनलाई प्रत्साहित गर्ने र बालबालिकालाई पुस्तक बोक्न सहजताका लागि वडाको वार्षिक कार्यक्रम अनुसार झोला वितरण गरिएको उनले बताए&nbsp;।</p><p style=\"font-size: 22px; line-height: 36px; color: rgb(42, 42, 42); font-family: Mukta, -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, Arial, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;;\">वडा कार्यालयले यसअघि यहाँका महिलाहरुलाई झोला बुन्ने तालिम दिएको थियो&nbsp;। तालिम पश्चात बनेको झोला खरिद गरेर वडाले वितरण गरेको जनाएको छ&nbsp;।</p><p style=\"font-size: 22px; line-height: 36px; color: rgb(42, 42, 42); font-family: Mukta, -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, Arial, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;;\">वडा कार्यालयका अनुसार मयम मावि सहित जनता, पाथीभरा, नाम्चेडाँडाचौतारा, जनकल्याण, महाकाली, गौरीशंकर र पाथीभरा माता आधारभूत विद्यालयका विद्यार्थीलाई झोला वितरण गरिएको हो&nbsp;।</p>'),
(22, '/uploads/sports/image-1767008930866-872679516.jpg', 'भोजपुरका २,६५० घरधुरीमा ‘एक घर एक धारा’', 'sdcsac', '2025-12-29 11:48:50', 'sxsa', NULL, '2025-12-29 11:48:50', '2025-12-29 11:48:50', '<p style=\"font-size: 22px !important; line-height: 36px; margin-top: 0.2em;\">आयोजनामार्फत भोजपुर बजार क्षेत्रसहित छ वटा वडाका दुई हजार ६५० घरधुरीमा ‘एक घर एक धारा’ जडान गरिएको सिलिचुङ खानेपानी तथा सरसफाइ मूल उपभोक्ता समितिले जनाएको छ&nbsp;। समितिका कार्यालय प्रमुख कृष्णसागर तामाङका अनुसार आयोजना सञ्चालनपछि बजार तथा आसपासका वडामा देखिँदै आएको चरम खानेपानी समस्या हटेको हो&nbsp;।</p><p style=\"font-size: 22px !important; line-height: 36px;\">भुल्के मुहान, डढुवा मुहान, जोरसाघु मुहान, तीनधारे मुहान र तीन भँगाले गरी पाँच वटा मुहानबाट पानी सङ्कलन गरी स्थानीय नागरिकको घरघरमा वितरण गरिएको समितिका अध्यक्ष तुफान किरातले जानकारी दिए&nbsp;। स्थानीयलाई शुद्ध खानेपानी उपलब्ध गराउने उद्देश्यले आयोजनाअन्तर्गत दुई वटा पानी प्रशोधन केन्द्रसमेत सञ्चालनमा ल्याइएको छ&nbsp;।</p><p style=\"font-size: 22px !important; line-height: 36px;\">\'स्थानीय नागरिकलाई सहज रूपमा खानेपानी व्यवस्था गर्ने लक्ष्यका साथ काम गरिरहेका छौँ,\' अध्यक्ष किरातले भने, \'आयोजना सञ्चालनमा आएपछि बजार क्षेत्रसँगै आसपासका वडाका नागरिकको पानीको समस्या हटेको छ&nbsp;।\'</p><p style=\"font-size: 22px !important; line-height: 36px;\">आयोजनामार्फत पानी वितरणका लागि १० हजार ९५ लिटर क्षमताका ११ वटा ट्याङ्की निर्माण गरी पानी वितरण भइरहेको छ&nbsp;। यस आयोजनाबाट भोजपुर नगरपालिका–५, ६, ७, ८, ९ र १२ का नागरिकले खानेपानी उपभोग गर्दै आएका छन्&nbsp;।</p><div class=\"ekans-wrapper\" style=\"margin-top: 20px; margin-bottom: 20px;\"><div class=\"ekans-row\" style=\"display: flex; flex-wrap: wrap; width: 747.994px; align-items: center; justify-content: center; margin-right: -10px; margin-left: -10px;\"><div class=\"ekans-col portrait\" style=\"flex: 0 0 auto; width: 249.319px; padding: 10px; color: rgb(42, 42, 42); font-family: Mukta, -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, Arial, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;; font-size: 22px;\"><font color=\"#222222\"><span style=\"cursor: pointer; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; transition-duration: 0.3s; transition-timing-function: ease-in; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><a href=\"https://www.facebook.com/share/1CDvCZDEWZ/\" target=\"_blank\" style=\"cursor: pointer; text-decoration: none; color: rgb(34, 34, 34); transition: 0.3s ease-in;\"><img src=\"https://assets-cdn.ekantipur.com/uploads/source/ads/hardik-niskula-opd250250-3-08102025044708.jpg\" alt=\"Hardik IVF\" style=\"filter: none; background: rgb(221, 221, 221);\"></a></span></font></div><div><font color=\"#222222\"><br></font></div></div></div>'),
(23, '/uploads/sports/image-1767008989572-190065147.jpg', 'ताप्लेजुङमा २ हजार ४२ मतदाता बढे', 'dcsdc', '2025-12-29 11:49:49', 'asccas', NULL, '2025-12-29 11:49:49', '2025-12-29 11:49:49', '<div class=\"ekans-wrapper\" style=\"margin-top: 20px; margin-bottom: 20px;\"><div class=\"ekans-row\" style=\"display: flex; flex-wrap: wrap; width: 747.994px; align-items: center; justify-content: center; margin-right: -10px; margin-left: -10px;\"><div><p style=\"font-size: 22px; line-height: 36px; margin-top: 0.2em; color: rgb(42, 42, 42); font-family: Mukta, -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, Arial, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;;\">जिल्ला निर्वाचन कार्यालयले अन्तिम मतदाता नामावली प्रकाशित गर्दै पुरुष ४८ हजार २ सय ८५ र महिला ४२ हजार ४२ भएको जनाएको हो&nbsp;। पुरुषको तुलनामा महिला मतदाता ६ हजार २ सय ४३ कम छन्&nbsp;। यो आगामी फागुन २० गते १८ वर्ष उमेर पुगेर २१ गते मतदान गर्न पाउनेको सङ्ख्या हो&nbsp;।</p><p style=\"font-size: 22px; line-height: 36px; color: rgb(42, 42, 42); font-family: Mukta, -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, Arial, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;;\">२०७९ को प्रतिनिधि तथा प्रदेशसभा निर्वाचनको तुलनामा २ हजार ४२ मतदाता थपिएका छन्&nbsp;। ०७९ मा ८८ हजार २ सय ८५ मतदाता थिए&nbsp;।</p><p style=\"font-size: 22px; line-height: 36px; color: rgb(42, 42, 42); font-family: Mukta, -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, Arial, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;;\">निर्वाचन कार्यालयका सूचना अधिकारी वान्दवराज ‘विपिन’ दुलालका अनुसार नौ स्थानीय तह रहेको जिल्लामा सबैभन्दा बढी फुङलिङ नगरपालिकामा १८ हजार १ सय ९० मतदाता छन्&nbsp;। सबैभन्दा कम मिक्वाखोला गाउँपालिकामा ६ हजार ९ सय ४८ जना छन्&nbsp;।</p><p style=\"font-size: 22px; line-height: 36px; color: rgb(42, 42, 42); font-family: Mukta, -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, Arial, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;;\">सिरिजङ्गामा ११ हजार ६ सय ६४, पाथीभरा याङवरकमा ९ हजार ७ सय ४१, आठराई त्रिबेणीमा ९ हजार ५ सय १, फक्ताङलुङमा ९ हजार ३ सय, सिदिङ्वामा ८ हजार ९ सय १५, मेरिङदेनमा ८ हजार ६ सय १२ र मैवाखोला गाउँपालिकामा ७ हजार ४ हजार ५६ मतदाता हुने दुलालले जानकारी दिए&nbsp;।</p></div></div></div>'),
(24, '/uploads/sports/image-1767009090328-966283810.jpg', 'भदौ २४ मा नख्खु कारागारबाट भागेका जबरजस्ती करणी मुद्दाका कैदी पक्राउ', 'sub भदौ २४ मा नख्खु कारागारबाट भागेका जबरजस्ती करणी मुद्दाका कैदी पक्राउ', '2025-12-29 11:51:30', 'jour', NULL, '2025-12-29 11:51:30', '2025-12-29 11:51:30', '<div class=\"ekans-wrapper\" style=\"margin-top: 20px; margin-bottom: 20px;\"><div class=\"ekans-row\" style=\"display: flex; flex-wrap: wrap; width: 747.994px; align-items: center; justify-content: center; margin-right: -10px; margin-left: -10px;\"><p style=\"font-size: 22px; line-height: 36px; margin-top: 0.2em; color: rgb(42, 42, 42); font-family: Mukta, -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, Arial, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;;\">चिचिला गाउँपालिका–५ का २९ वर्षीय अमित भनिने टीकाराम विश्वकर्मालाई पक्राउ गरेको जिल्ला प्रहरी कार्यालय सङ्खुवासभाका सूचना अधिकारी प्रहरी निरीक्षक धनबहादुर राजवंशीले जानकारी दिए&nbsp;। फरार रहेका विश्वकर्माको खोजीका लागि जिल्ला प्रहरी सङ्खुवासभाबाट खटिएको टोलीले विशेष सूचनाका आधारमा मोरङको बेलबारी नगरपालिका–४ स्थित आफन्तको घरमा लुकिछिपी बसिरहेको अवस्थामा शनिबार पक्राउ गरेको हो&nbsp;। उनी जबरजस्ती करणी मुद्दामा २०७५ पुस २७ गतेदेखि नख्खुमा कैद भुक्तान गरिरहेका थिए&nbsp;।</p><p style=\"font-size: 22px; line-height: 36px; color: rgb(42, 42, 42); font-family: Mukta, -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, Arial, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;;\">उनी भदौ २४ गते कारागारबाट फरार भएका थिए&nbsp;। जिल्लामा जेन-जी आन्दोलनका क्रममा भागेका सात कैदीलाई पक्राउ गरिसकेको प्रहरीले जनाएको छ&nbsp;। पक्राउ परेका विश्वकर्मालाई फैसला कार्यान्वयनका लागि आइतबार कारागार कार्यालय सङ्खुवासभामा बुझाइएको जिल्ला प्रहरी कार्यालयले जनाएको छ&nbsp;।</p></div></div>'),
(25, '/uploads/sports/image-1767010092287-326019442.jpg', 'भयरहित वातावरण बनाउन सञ्चार क्षेत्रको भूमिका महत्त्वपूर्ण : प्रहरी महानिरीक्षक कार्की', 'dscsdc', '2025-12-29 12:08:12', 'csasac', NULL, '2025-12-29 12:08:12', '2025-12-29 12:08:12', '<p style=\"font-size: 22px; line-height: 36px; margin-top: 0.2em; color: rgb(42, 42, 42); font-family: Mukta, -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, Arial, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;;\">लुम्बिनी प्रेस क्लबद्वारा आयोजित न्युज फेस्टिवलको समापनमा महानिरीक्षक कार्कीले प्रहरी र सञ्चारकर्मीबीचको सम्बन्धलाई नङ र मासुको रूपमा चित्रित गर्दै लुकेका अपराध बाहिर ल्याउन सञ्चार क्षेत्रले निर्वाह गरेको भूमिका महत्त्वपूर्ण भएको बताए&nbsp;।</p><p style=\"font-size: 22px; line-height: 36px; color: rgb(42, 42, 42); font-family: Mukta, -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, Arial, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;;\">लुम्बिनीस्थित बेबी बुद्धमा सोमबार न्युज फेस्टिवलको समापन एवं क्लबको स्थापना दिवसको अवसर पारेर आयोजित कार्यक्रममा उनले खोज पत्रकारितामार्फत लुकेका कैयौं अपराध बाहिर ल्याउन सञ्चारकर्मीले सहयोग पुर्‍याइरहेको बताए&nbsp;। ‘कहिलेकाहीँ घटनास्थलमा प्रहरी भन्दा पहिले सञ्चारकर्मी पुगेर अपराधमा संलग्नलाई पक्राउ गर्ने आधार र प्रमाण पाउँदा अनुसन्धानमा पनि सहयोग पुगेको छ,’ उनले भने&nbsp;। अफवाह, मिथ्या र भ्रामक सूचना चिर्न पत्रकारले तथ्यमा आधारित, सन्तुलित र जिम्मेवार समाचार दिएर नागरिकमा चेतनाको स्तर बढाउनु पर्ने उनले बताए&nbsp;।</p><p style=\"font-size: 22px; line-height: 36px; color: rgb(42, 42, 42); font-family: Mukta, -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, Arial, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;;\">लुम्बिनी प्रेस क्लबको ११ औं स्थापना दिवसका अवसरमा आयोजित हेरिटेज वाकको पनि महानिरीक्षक कार्कीले शुभारम्भ गरेका थिए&nbsp;। पर्सा चोकदेखि हेरिटेज वाक गर्दै टोली बेबी बुद्धमा पुगेर समापन गरिएको थियो&nbsp;।</p><p style=\"font-size: 22px; line-height: 36px; color: rgb(42, 42, 42); font-family: Mukta, -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, Arial, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;;\">कार्यक्रममा नेपाल पत्रकार महासंघ अध्यक्ष निर्मला शर्मा, प्रेस काउन्सिल अध्यक्ष डा. कुमार आचार्य, लुम्बिनी सांस्कृतिक नगरपालिकाका कार्यवाहक प्रमुख कल्पना हरिजन, लुम्बिनी विकास कोषका सदस्य-सचिव दीपक श्रेष्ठलगायतले सञ्चार क्षेत्रको भूमिकाबारे बोलेका थिए&nbsp;। तीन दिने न्युज फेस्टिवलमा नेपाल र भारतका पत्रकार, पर्यटन व्यवसायी, उद्यमी, भिक्षु र लामा गुरु सहभागी थिए&nbsp;।</p>');

-- --------------------------------------------------------

--
-- Table structure for table `teams`
--

CREATE TABLE `teams` (
  `id` int(11) NOT NULL,
  `name` varchar(255) NOT NULL,
  `position` varchar(255) NOT NULL,
  `imageUrl` varchar(255) DEFAULT NULL,
  `displayOrder` int(11) NOT NULL DEFAULT 0,
  `isActive` tinyint(1) NOT NULL DEFAULT 1,
  `bio` text DEFAULT NULL,
  `email` varchar(255) DEFAULT NULL,
  `phone` varchar(255) DEFAULT NULL,
  `socialLinks` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`socialLinks`)),
